// ============================================================
// Terraclima — summaryImmersive Length Polish
// ============================================================
//
// Expands summaryImmersive paragraphs that shipped under the ~80-150
// word target band. Each expansion appends new sentences grounded in
// the place's own biome, drivers, koppen class, and risk notes — the
// original authored sentence(s) are kept verbatim and extended, never
// replaced. Applied at load time in places.ts as an overlay that only
// replaces summaryImmersive when the authored text is still present
// as a prefix (so a later hand-edit of the base copy is never silently
// overridden by this stale expansion).
// ============================================================

export const SUMMARY_IMMERSIVE_POLISH: Record<string, { original: string; expanded: string }> = {
  "ajijic-lake-chapala-mx": { original: "Ajijic sits on Lake Chapala's north shore at a highland elevation that trims tropical heat while the lake softens daily extremes. The dry season is bright and warm; the wet season arrives with afternoon storms that green the surrounding slopes. Compared with Guadalajara, the lakeshore is smaller, breezier, and more temperature-stable, which is why it has become one of Mexico's best-known year-round comfort climates.", expanded: "Ajijic sits on Lake Chapala's north shore at a highland elevation that trims tropical heat while the lake softens daily extremes. The dry season is bright and warm; the wet season arrives with afternoon storms that green the surrounding slopes. Compared with Guadalajara, the lakeshore is smaller, breezier, and more temperature-stable, which is why it has become one of Mexico's best-known year-round comfort climates. The rhythm holds most years: summer highs near 29°C, winter lows near 8°C, and about 776 mm of precipitation overall. Chapala / Ajijic sits inside highland subtropical lake basin with dry forest slopes, and that biome is as much a product of the local climate as a backdrop to it." },
  "alamos-mx": { original: "Álamos sits in the foothills of the Sierra Madre Occidental at 406 m. The North American Monsoon pushes moisture here reliably from July through September, transforming the dry thornscrub into luxuriant green. Winters are warm, dry, and bright — one of the mildest winter climates in northern Mexico.", expanded: "Álamos sits in the foothills of the Sierra Madre Occidental at 406 m. The North American Monsoon pushes moisture here reliably from July through September, transforming the dry thornscrub into luxuriant green. Winters are warm, dry, and bright — one of the mildest winter climates in northern Mexico. Álamos rewards people who plan around the monsoon-edge zone pattern rather than treating it as scenery. Drought and extreme summer heat are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 397 mm, with summer afternoons averaging near 37°C and winter nights near 9°C — the numbers a scouting trip should actually check." },
  "anchorage-ak": { original: "Cook Inlet’s tides and sea ice modulate winter temperatures; Chugach orographics enhance snowfall on the east side. Summer days are long and mild; smoke from interior fires occasionally pools.", expanded: "Cook Inlet’s tides and sea ice modulate winter temperatures; Chugach orographics enhance snowfall on the east side. Summer days are long and mild; smoke from interior fires occasionally pools. The draw for most visitors is straightforward — Chugach access — but the climate is what keeps people coming back. Extreme winter cold and wildfire smoke are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 428 mm, with summer afternoons averaging near 19°C and winter nights near -11°C — the numbers a scouting trip should actually check." },
  "apalachicola-fl": { original: "Apalachicola sits where the Apalachicola River meets its eponymous bay — one of the most productive estuaries on the Gulf. The climate is subtropical but the marine moderation and onshore breezes keep summer afternoons below the Deep-South interior inferno. Oyster reefs, tupelo-honey swamps, and pine flatwoods together paint a distinctly regional picture.", expanded: "Apalachicola sits where the Apalachicola River meets its eponymous bay — one of the most productive estuaries on the Gulf. The climate is subtropical but the marine moderation and onshore breezes keep summer afternoons below the Deep-South interior inferno. Oyster reefs, tupelo-honey swamps, and pine flatwoods together paint a distinctly regional picture. The draw for most visitors is straightforward — oysters — but the climate is what keeps people coming back. Coastal storm-surge risk and flooding are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "asheville-nc": { original: "Asheville sits at 650 m in the French Broad basin. The elevation produces summers significantly milder than the Piedmont or deep South — July afternoons average around 28°C versus 32°C in Charlotte 200 km east. Winters are mild with occasional snow; the surrounding ridges receive much more. The cove forests, orchards, and mild climate have attracted people for 150 years.", expanded: "Asheville sits at 650 m in the French Broad basin. The elevation produces summers significantly milder than the Piedmont or deep South — July afternoons average around 28°C versus 32°C in Charlotte 200 km east. Winters are mild with occasional snow; the surrounding ridges receive much more. The cove forests, orchards, and mild climate have attracted people for 150 years. Asheville rewards people who plan around the mild-winter foothills pattern rather than treating it as scenery. Flooding and wildfire smoke are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "astoria-or": { original: "Astoria perches at the Columbia's mouth where river, ocean, and coastal mountains collide. The annual temperature range is among the continent's narrowest — winter highs of 9°C and summer highs of 20°C. Sunshine is rare (fewer than 70 sunny days a year); fog and marine cloud dominate. The place has the soul of a storm-lashed port because that is literally what it is.", expanded: "Astoria perches at the Columbia's mouth where river, ocean, and coastal mountains collide. The annual temperature range is among the continent's narrowest — winter highs of 9°C and summer highs of 20°C. Sunshine is rare (fewer than 70 sunny days a year); fog and marine cloud dominate. The place has the soul of a storm-lashed port because that is literally what it is. The rhythm holds most years: summer highs near 20°C, winter lows near 3°C, and about 2263 mm of precipitation overall. Marine layer is doing quiet work behind the numbers, and it is why Astoria does not feel like a generic Cfb town." },
  "austin-tx": { original: "Austin’s climate is a blend of Gulf moisture, plateau dry lines, and urban expansion that strengthens nocturnal heat. Hill-country storms fire on boundaries between air masses; flash flooding along the Colorado is a recurring story.", expanded: "Austin’s climate is a blend of Gulf moisture, plateau dry lines, and urban expansion that strengthens nocturnal heat. Hill-country storms fire on boundaries between air masses; flash flooding along the Colorado is a recurring story. It suits tech workers more than casual visitors chasing a postcard version of the river-valley moderation. Flooding and drought are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 881 mm, with summer afternoons averaging near 36°C and winter nights near 5°C — the numbers a scouting trip should actually check." },
  "bacalar-mx": { original: "Bacalar sits on a freshwater lagoon famous for the way karst-leached limestone produces cyan, turquoise, and deep-blue water in distinct layers. The climate is tropical-isothermal: highs 30–33°C, lows 17–23°C, and small annual variation. Dry-season trade winds keep the humidity tolerable; wet season brings afternoon thunderstorms and occasional hurricane remnants from either coast.", expanded: "Bacalar sits on a freshwater lagoon famous for the way karst-leached limestone produces cyan, turquoise, and deep-blue water in distinct layers. The climate is tropical-isothermal: highs 30–33°C, lows 17–23°C, and small annual variation. Dry-season trade winds keep the humidity tolerable; wet season brings afternoon thunderstorms and occasional hurricane remnants from either coast. Karst infiltration is doing quiet work behind the numbers, and it is why Bacalar does not feel like a generic Aw town. Expect summer afternoons near 34°C and winter nights near 19°C as the baseline, with about 1166 mm of precipitation across a typical year." },
  "baie-saint-paul-qc": { original: "Baie-Saint-Paul sits where the Gouffre River reaches the broad St. Lawrence estuary, backed immediately by the Charlevoix hills. Summer is gentler than inland Quebec because estuary air trims heat; winter remains snowy and cold as storms lift into the Laurentians. The result is a compact cultural landscape of river meadows, apple pockets, forested slopes, and bright shoulder seasons that feel more coastal than the map suggests.", expanded: "Baie-Saint-Paul sits where the Gouffre River reaches the broad St. Lawrence estuary, backed immediately by the Charlevoix hills. Summer is gentler than inland Quebec because estuary air trims heat; winter remains snowy and cold as storms lift into the Laurentians. The result is a compact cultural landscape of river meadows, apple pockets, forested slopes, and bright shoulder seasons that feel more coastal than the map suggests. It suits artists more than casual visitors chasing a postcard version of the fjord / inlet coast. Extreme winter cold and severe-storm risk are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "banff-ab": { original: "Banff's climate is mountain continental: long cold winters, mild short summers, and dramatic chinook warm spells that erase snowpack overnight. Precipitation is moderate and favors summer convection; shoulder seasons are crisp and dry.", expanded: "Banff's climate is mountain continental: long cold winters, mild short summers, and dramatic chinook warm spells that erase snowpack overnight. Precipitation is moderate and favors summer convection; shoulder seasons are crisp and dry. The rhythm holds most years: summer highs near 21°C, winter lows near -13°C, and about 463 mm of precipitation overall. The Köppen Dfc label is the broad-stroke summary; the chinook corridor pattern is the fine-grained read a visit actually delivers. Banff rewards people who plan around the chinook corridor pattern rather than treating it as scenery." },
  "bar-harbor-me": { original: "Bar Harbor sits on Mount Desert Island where sea fog rolls in on summer afternoons and fall colors are electric against dark granite. Winter is cold but moderated relative to interior Maine thanks to water; nor'easters bring heavy mixed precipitation.", expanded: "Bar Harbor sits on Mount Desert Island where sea fog rolls in on summer afternoons and fall colors are electric against dark granite. Winter is cold but moderated relative to interior Maine thanks to water; nor'easters bring heavy mixed precipitation. The draw for most visitors is straightforward — Acadia — but the climate is what keeps people coming back. Severe-storm risk and coastal storm-surge risk are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 1367 mm, with summer afternoons averaging near 24°C and winter nights near -8°C — the numbers a scouting trip should actually check." },
  "beverly-shores-in": { original: "Beverly Shores is where continental air masses first feel the thermal mass of Lake Michigan: delayed spring warming, abundant winter cloud when cold air crosses open water, and frequent afternoon wind shifts on stable summer days. The microclimate supports boreal relicts and rare orchids in protected swales — a biogeographic fingerprint of the lake.", expanded: "Beverly Shores is where continental air masses first feel the thermal mass of Lake Michigan: delayed spring warming, abundant winter cloud when cold air crosses open water, and frequent afternoon wind shifts on stable summer days. The microclimate supports boreal relicts and rare orchids in protected swales — a biogeographic fingerprint of the lake. The honest tradeoff is severe-storm risk, which runs elevated and worsening and is worth weighing against the mild-sounding averages. Beverly Shores rewards people who plan around the lake-effect snowbelt pattern rather than treating it as scenery." },
  "bismarck-nd": { original: "Bismarck sits in one of the continent’s starkest annual temperature ranges. Arctic highs in winter deliver brilliant cold and dry air; summer opens to dryline thunderstorms and occasional severe hail. Chinook warming on eastern Rocky lee slopes occasionally interrupts mid-winter cold. Lake Sakakawea moderates lee-side microclimates only slightly — continentality dominates.", expanded: "Bismarck sits in one of the continent’s starkest annual temperature ranges. Arctic highs in winter deliver brilliant cold and dry air; summer opens to dryline thunderstorms and occasional severe hail. Chinook warming on eastern Rocky lee slopes occasionally interrupts mid-winter cold. Lake Sakakawea moderates lee-side microclimates only slightly — continentality dominates. Bismarck rewards people who plan around the subarctic continental pattern rather than treating it as scenery. Extreme winter cold and drought are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "block-island-ri": { original: "Block Island is small enough that every road is within a mile of water. That geometry means marine air dominates; heat waves are muted relative to Hartford or even Providence. Winter storms are oceanic and windy; summer is mild with persistent humidity. The island’s conservation lands preserve a rare Atlantic coastal grassland–heath mosaic tuned to salt spray.", expanded: "Block Island is small enough that every road is within a mile of water. That geometry means marine air dominates; heat waves are muted relative to Hartford or even Providence. Winter storms are oceanic and windy; summer is mild with persistent humidity. The island’s conservation lands preserve a rare Atlantic coastal grassland–heath mosaic tuned to salt spray. The rhythm holds most years: summer highs near 25°C, winter lows near -3°C, and about 1233 mm of precipitation overall. Marine layer is the mechanism, layering a hyper-maritime pattern onto the Cfb-class averages a map alone would suggest." },
  "boone-nc": { original: "Boone perches at 995 m on the Blue Ridge Escarpment, high enough that its climate resembles New Hampshire more than the Carolina Piedmont below. Summer afternoons stay in the low-to-mid 20s °C; winters bring snow and real cold; cloudy-windy days are common. The Appalachian Trail passes through; the landscape carries an ecological character more northern than its latitude suggests.", expanded: "Boone perches at 995 m on the Blue Ridge Escarpment, high enough that its climate resembles New Hampshire more than the Carolina Piedmont below. Summer afternoons stay in the low-to-mid 20s °C; winters bring snow and real cold; cloudy-windy days are common. The Appalachian Trail passes through; the landscape carries an ecological character more northern than its latitude suggests. It suits summer-heat refugees more than casual visitors chasing a postcard version of the mild-winter foothills. Flooding and severe-storm risk are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "borrego-springs-ca": { original: "Borrego Springs sits in a bowl ringed by 2000 m peaks that cast a deep rain shadow. Winters are glorious: 22°C afternoons, 8°C nights, clear sky after clear sky. Summers are apocalyptic — 42°C is normal, dew points often below 10 °C, and the only reasonable activity is waiting for dark. The International Dark-Sky Community designation reflects that: no light leaks from here to anywhere.", expanded: "Borrego Springs sits in a bowl ringed by 2000 m peaks that cast a deep rain shadow. Winters are glorious: 22°C afternoons, 8°C nights, clear sky after clear sky. Summers are apocalyptic — 42°C is normal, dew points often below 10 °C, and the only reasonable activity is waiting for dark. The International Dark-Sky Community designation reflects that: no light leaks from here to anywhere. The honest tradeoff is drought, which runs very-high and worsening and is worth weighing against the mild-sounding averages. It suits winter-only retirees more than casual visitors chasing a postcard version of the desert oasis." },
  "boulder-co": { original: "Boulder's climate is defined by descent. When westerly winds cross the Divide, they compress and warm on the lee side, producing sudden 20°C warm-ups mid-winter. Snow vanishes within a day; the sun feels stronger than its latitude suggests. Summers are dry and warm, with afternoon convective thunderstorms climbing the range.", expanded: "Boulder's climate is defined by descent. When westerly winds cross the Divide, they compress and warm on the lee side, producing sudden 20°C warm-ups mid-winter. Snow vanishes within a day; the sun feels stronger than its latitude suggests. Summers are dry and warm, with afternoon convective thunderstorms climbing the range. Boulder sits inside mixed-grass prairie transition, and that biome is as much a product of the local climate as a backdrop to it. Expect summer afternoons near 30°C and winter nights near -5°C as the baseline, with about 492 mm of precipitation across a typical year." },
  "bozeman-mt": { original: "Bozeman sits at 1474 m in the Gallatin Valley, a foothill basin between the Bridgers, Gallatins, and Tobacco Roots. Chinooks punctuate winters; diurnal swings are significant; sunshine is abundant. Summer afternoons reach 27–29°C but seldom higher thanks to the elevation. The climate is drier and sunnier than Montana's western valleys and cooler-summer than its eastern plains.", expanded: "Bozeman sits at 1474 m in the Gallatin Valley, a foothill basin between the Bridgers, Gallatins, and Tobacco Roots. Chinooks punctuate winters; diurnal swings are significant; sunshine is abundant. Summer afternoons reach 27–29°C but seldom higher thanks to the elevation. The climate is drier and sunnier than Montana's western valleys and cooler-summer than its eastern plains. The honest tradeoff is wildfire, which runs elevated and worsening and is worth weighing against the mild-sounding averages. The draw for most visitors is straightforward — Yellowstone north — but the climate is what keeps people coming back." },
  "broken-bow-ok": { original: "Broken Bow and the Mountain Fork corridor punch above the surrounding plains in annual precipitation and forest cover. Upslope flow ahead of Gulf lows enhances rainfall; reservoirs and rivers add local moisture. Summers remain hot, but canopy and shade produce perceptible relief compared to open pasture.", expanded: "Broken Bow and the Mountain Fork corridor punch above the surrounding plains in annual precipitation and forest cover. Upslope flow ahead of Gulf lows enhances rainfall; reservoirs and rivers add local moisture. Summers remain hot, but canopy and shade produce perceptible relief compared to open pasture. It suits outdoor families more than casual visitors chasing a postcard version of the piedmont transition. Flooding and extreme summer heat are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 1402 mm, with summer afternoons averaging near 33°C and winter nights near 0°C — the numbers a scouting trip should actually check." },
  "brookings-or": { original: "Brookings is already mild for the Oregon coast, but its claim to fame is episodic winter warmth: when pressure patterns align, air descends through the Chetco River corridor and compresses, producing rapid jumps that can melt frost in minutes while Astoria shivers. Baseline climate is still hyper-maritime — cool wet winters, foggy Junes, and summer highs that rarely tax a sweater.", expanded: "Brookings is already mild for the Oregon coast, but its claim to fame is episodic winter warmth: when pressure patterns align, air descends through the Chetco River corridor and compresses, producing rapid jumps that can melt frost in minutes while Astoria shivers. Baseline climate is still hyper-maritime — cool wet winters, foggy Junes, and summer highs that rarely tax a sweater. The honest tradeoff is severe-storm risk, which runs elevated and worsening and is worth weighing against the mild-sounding averages. It suits storm watchers more than casual visitors chasing a postcard version of the gap / gorge wind corridor." },
  "buffalo-ny": { original: "Buffalo’s reputation is snow, but the mechanism is physics: cold air over warm open water, convection, and shoreline convergence. Summer benefits from lake cooling and convection along the breeze front.", expanded: "Buffalo’s reputation is snow, but the mechanism is physics: cold air over warm open water, convection, and shoreline convergence. Summer benefits from lake cooling and convection along the breeze front. The rhythm holds most years: summer highs near 26°C, winter lows near -6°C, and about 1081 mm of precipitation overall. Buffalo sits inside Great Lakes mixed forest, and that biome is as much a product of the local climate as a backdrop to it. It suits urban families more than casual visitors chasing a postcard version of the lake-effect snowbelt." },
  "burkes-garden-va": { original: "Burkes Garden is a geomorphic sink surrounded by continuous ridges. On clear, calm nights, katabatic drainage fills the bowl with dense air that cannot easily exit; the result is systematically lower minima than surrounding slopes at similar elevation. Agronomists and orchardists treat the floor and rim as different climates; atmospheric scientists use the basin as an eastern analog to western basin cold pools.", expanded: "Burkes Garden is a geomorphic sink surrounded by continuous ridges. On clear, calm nights, katabatic drainage fills the bowl with dense air that cannot easily exit; the result is systematically lower minima than surrounding slopes at similar elevation. Agronomists and orchardists treat the floor and rim as different climates; atmospheric scientists use the basin as an eastern analog to western basin cold pools. The honest tradeoff is extreme winter cold, which runs elevated and improving and is worth weighing against the mild-sounding averages. The draw for most visitors is straightforward — ridge vistas — but the climate is what keeps people coming back." },
  "burlington-vt": { original: "Burlington gets lake-effect snow early in winter when the lake is still unfrozen; spring 'fifth season' fog is famous. Summer afternoons are milder than Boston or Hartford for latitude thanks to lake breezes. Fall color arrives with crisp Canadian air behind cold fronts.", expanded: "Burlington gets lake-effect snow early in winter when the lake is still unfrozen; spring 'fifth season' fog is famous. Summer afternoons are milder than Boston or Hartford for latitude thanks to lake breezes. Fall color arrives with crisp Canadian air behind cold fronts. The rhythm holds most years: summer highs near 26°C, winter lows near -10°C, and about 1027 mm of precipitation overall. Lake effect is doing quiet work behind the numbers, and it is why Burlington does not feel like a generic Dfb town. Burlington rewards people who plan around the lake-moderated pattern rather than treating it as scenery." },
  "campeche-mx": { original: "Campeche receives summer deluges from tropical waves and autumn hurricanes; winter is warm and pleasant. Sea breezes moderate the heat but not the humidity. The low flat plain means surge and flood risk during strong storms.", expanded: "Campeche receives summer deluges from tropical waves and autumn hurricanes; winter is warm and pleasant. Sea breezes moderate the heat but not the humidity. The low flat plain means surge and flood risk during strong storms. The honest tradeoff is severe-storm risk, which runs very-high and worsening and is worth weighing against the mild-sounding averages. San Francisco de Campeche rewards people who plan around the hurricane-exposed coast pattern rather than treating it as scenery. Tropical-cyclone exposure is doing quiet work behind the numbers, and it is why San Francisco de Campeche does not feel like a generic Aw town." },
  "cape-may-nj": { original: "Cape May is a classic barrier-style energy balance problem: water on three sides, low elevation, and tree canopy that knits humidity into every summer afternoon. Autumn can deliver warm ocean swimming while inland New Jersey cools; winter alternates between mild marine air and biting Arctic outbreaks when continental highs wedge behind the Appalachians.", expanded: "Cape May is a classic barrier-style energy balance problem: water on three sides, low elevation, and tree canopy that knits humidity into every summer afternoon. Autumn can deliver warm ocean swimming while inland New Jersey cools; winter alternates between mild marine air and biting Arctic outbreaks when continental highs wedge behind the Appalachians. Cape May sits inside maritime holly forest and dune scrub, and that biome is as much a product of the local climate as a backdrop to it. Expect summer afternoons near 29°C and winter nights near -1°C as the baseline, with about 1135 mm of precipitation across a typical year." },
  "charleston-sc": { original: "Charleston's low-country location on the Ashley-Cooper estuary produces humid-subtropical summers softened by reliable sea-breeze development by early afternoon — enough to bring 2–4°C of relief on most days compared to inland South Carolina. Winters are mild; frost is infrequent. Hurricanes are the existential climate factor; the statistical path brings major storms every decade or two.", expanded: "Charleston's low-country location on the Ashley-Cooper estuary produces humid-subtropical summers softened by reliable sea-breeze development by early afternoon — enough to bring 2–4°C of relief on most days compared to inland South Carolina. Winters are mild; frost is infrequent. Hurricanes are the existential climate factor; the statistical path brings major storms every decade or two. Diurnal sea breeze is doing quiet work behind the numbers, and it is why Charleston does not feel like a generic Cfa town. Expect summer afternoons near 32°C and winter nights near 6°C as the baseline, with about 1278 mm of precipitation across a typical year." },
  "charlottetown-pei": { original: "PEI is a sandbar in the Gulf: winters are snowy and windy; summers are mild with persistent breezes that keep beaches comfortable. Spring fog is common; fall is peak tourism for harvest and lighthouses.", expanded: "PEI is a sandbar in the Gulf: winters are snowy and windy; summers are mild with persistent breezes that keep beaches comfortable. Spring fog is common; fall is peak tourism for harvest and lighthouses. Charlottetown rewards people who plan around the cool-summer maritime pattern rather than treating it as scenery. Severe-storm risk and coastal storm-surge risk are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 1172 mm, with summer afternoons averaging near 23°C and winter nights near -8°C — the numbers a scouting trip should actually check." },
  "chattanooga-tn": { original: "Chattanooga sits where the Tennessee River cuts a gap through plateau country, creating scenic overlooks and localized wind channeling. Summers are hot and humid; spring and fall bring severe thunderstorms along frontal boundaries. Winter is short with occasional light snow on surrounding ridges.", expanded: "Chattanooga sits where the Tennessee River cuts a gap through plateau country, creating scenic overlooks and localized wind channeling. Summers are hot and humid; spring and fall bring severe thunderstorms along frontal boundaries. Winter is short with occasional light snow on surrounding ridges. The honest tradeoff is flooding, which runs elevated and worsening and is worth weighing against the mild-sounding averages. Chattanooga rewards people who plan around the river-valley moderation pattern rather than treating it as scenery. River-valley moderation is doing quiet work behind the numbers, and it is why Chattanooga does not feel like a generic Cfa town." },
  "churchill-mb": { original: "Churchill sits on Hudson Bay's west shore at 58.8° latitude. Hudson Bay freezes fully in winter, producing continental-cold conditions with lows below −30°C; during the open-water season (July–November), it acts as a heat-and-moisture source, moderating autumn temperatures and generating lake-effect-style snow. Polar bears gather here in October, waiting for the bay to re-freeze. Summer is brief, cool, and buggy.", expanded: "Churchill sits on Hudson Bay's west shore at 58.8° latitude. Hudson Bay freezes fully in winter, producing continental-cold conditions with lows below −30°C; during the open-water season (July–November), it acts as a heat-and-moisture source, moderating autumn temperatures and generating lake-effect-style snow. Polar bears gather here in October, waiting for the bay to re-freeze. Summer is brief, cool, and buggy. The honest tradeoff is extreme winter cold, which runs very-high and improving and is worth weighing against the mild-sounding averages. Churchill rewards people who plan around the subarctic continental pattern rather than treating it as scenery." },
  "clayton-ga": { original: "Clayton is far enough south to feel subtropical in spring, but elevation and orographic cloudiness on moist southerly flow keep midsummer heat human. Waterfalls and north-facing coves stay shockingly cool; south-facing ridges open to sun for viticulture experiments. The contrast with Atlanta’s heat island is not subtle — it is a different regional climate at the same latitude band.", expanded: "Clayton is far enough south to feel subtropical in spring, but elevation and orographic cloudiness on moist southerly flow keep midsummer heat human. Waterfalls and north-facing coves stay shockingly cool; south-facing ridges open to sun for viticulture experiments. The contrast with Atlanta’s heat island is not subtle — it is a different regional climate at the same latitude band. It suits remote workers more than casual visitors chasing a postcard version of the mild-winter foothills. Flooding and severe-storm risk are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "coatepec-mx": { original: "Coatepec sits on the windward Gulf slope of the Sierra Madre Oriental at 1250 m, where Atlantic moisture condenses reliably on hillside slopes. Coffee was introduced in the early 1800s and the town developed around an exceptional climate — cool, humid, mild, and perpetually misty.", expanded: "Coatepec sits on the windward Gulf slope of the Sierra Madre Oriental at 1250 m, where Atlantic moisture condenses reliably on hillside slopes. Coffee was introduced in the early 1800s and the town developed around an exceptional climate — cool, humid, mild, and perpetually misty. The Köppen Cfb label is the broad-stroke summary; the cloud forest pattern is the fine-grained read a visit actually delivers. Expect summer afternoons near 28°C and winter nights near 11°C as the baseline, with about 1474 mm of precipitation across a typical year." },
  "cody-wy": { original: "Cody sits at the east edge of the Absaroka Range in the Bighorn Basin's rain shadow. The climate is dry (around 250 mm annual precipitation), sunny, and marked by dramatic chinook events: winter westerlies descending the Absarokas can lift temperatures 25°C in a day. Snow vanishes overnight. The basin's summers are warm but dry, and the proximity to Yellowstone makes the town a gateway.", expanded: "Cody sits at the east edge of the Absaroka Range in the Bighorn Basin's rain shadow. The climate is dry (around 250 mm annual precipitation), sunny, and marked by dramatic chinook events: winter westerlies descending the Absarokas can lift temperatures 25°C in a day. Snow vanishes overnight. The basin's summers are warm but dry, and the proximity to Yellowstone makes the town a gateway. At 1555 m, the setting — Bighorn Basin east of the Absarokas — does most of the explanatory work here. Expect summer afternoons near 28°C and winter nights near -9°C as the baseline, with about 265 mm of precipitation across a typical year." },
  "columbia-sc": { original: "Columbia sits just below the fall line: hotter summers than Charleston, colder winter snaps than the coast. The Congaree moderates some frost near the floodplain; urban expansion strengthens nocturnal heat.", expanded: "Columbia sits just below the fall line: hotter summers than Charleston, colder winter snaps than the coast. The Congaree moderates some frost near the floodplain; urban expansion strengthens nocturnal heat. The rhythm holds most years: summer highs near 33°C, winter lows near 2°C, and about 1263 mm of precipitation overall. Columbia sits inside pine savanna and bottomland hardwood, and that biome is as much a product of the local climate as a backdrop to it. The draw for most visitors is straightforward — Congaree NP — but the climate is what keeps people coming back." },
  "crested-butte-co": { original: "Crested Butte sits 360 m above Gunnison in its own valley and yet — counterintuitively — often runs warmer on winter mornings because its ridgetop pocket sits above Gunnison's cold pool on inversion days. Summer is short, cool, and spectacular: July afternoon highs in the low 20s, a wildflower bloom unrivaled in the Rockies. Winters are deep, snowy, and magnificent.", expanded: "Crested Butte sits 360 m above Gunnison in its own valley and yet — counterintuitively — often runs warmer on winter mornings because its ridgetop pocket sits above Gunnison's cold pool on inversion days. Summer is short, cool, and spectacular: July afternoon highs in the low 20s, a wildflower bloom unrivaled in the Rockies. Winters are deep, snowy, and magnificent. The honest tradeoff is extreme winter cold, which runs high and improving and is worth weighing against the mild-sounding averages. It suits skiers more than casual visitors chasing a postcard version of the alpine tundra." },
  "creston-bc": { original: "Creston sits in a broad valley between two great ranges. Partial rain shadow, long summer days, fertile silt soils, and extensive wetlands support a steady fruit and grain economy.", expanded: "Creston sits in a broad valley between two great ranges. Partial rain shadow, long summer days, fertile silt soils, and extensive wetlands support a steady fruit and grain economy. River-valley moderation is doing quiet work behind the numbers, and it is why Creston does not feel like a generic Dfb town. Expect summer afternoons near 27°C and winter nights near -5°C as the baseline, with about 633 mm of precipitation across a typical year. The honest tradeoff is wildfire, which runs elevated and worsening and is worth weighing against the mild-sounding averages." },
  "cuauhtemoc-mx": { original: "Cuauhtémoc sits on the central Chihuahuan plateau at 2060 m. Mennonite settlers from Canada brought their dryland apple expertise here in the 1920s and developed what is now the country's largest apple-growing region. The climate is ideal for the fruit: chill hours are adequate, summers dry and sunny, nights cool enough for skin color development. The winter can bring genuine cold and occasional snow.", expanded: "Cuauhtémoc sits on the central Chihuahuan plateau at 2060 m. Mennonite settlers from Canada brought their dryland apple expertise here in the 1920s and developed what is now the country's largest apple-growing region. The climate is ideal for the fruit: chill hours are adequate, summers dry and sunny, nights cool enough for skin color development. The winter can bring genuine cold and occasional snow. The Köppen BSk label is the broad-stroke summary; the high-desert escape pattern is the fine-grained read a visit actually delivers. Expect summer afternoons near 30°C and winter nights near 1°C as the baseline, with about 497 mm of precipitation across a typical year." },
  "cuernavaca-mx": { original: "Cuernavaca occupies a south-facing bench on the volcanic belt's flank, 1500 m above the tropical lowlands. Aztec emperors and Spanish viceroys retreated here for the climate: afternoons in the mid-to-high 20s year-round, nights cooling into the mid-teens, bougainvillea spilling off every wall. The rainy season arrives in June with dramatic afternoon convection off the volcanoes above, washing the air clean each evening. Winters are dry, bright, and warm.", expanded: "Cuernavaca occupies a south-facing bench on the volcanic belt's flank, 1500 m above the tropical lowlands. Aztec emperors and Spanish viceroys retreated here for the climate: afternoons in the mid-to-high 20s year-round, nights cooling into the mid-teens, bougainvillea spilling off every wall. The rainy season arrives in June with dramatic afternoon convection off the volcanoes above, washing the air clean each evening. Winters are dry, bright, and warm. The rhythm holds most years: summer highs near 28°C, winter lows near 11°C, and about 972 mm of precipitation overall." },
  "dawson-city-yt": { original: "Dawson City sits far inland near the Arctic Circle, where winter cold pools along the Yukon River and summer daylight runs long enough to push gardens fast. It is drier than many coastal northern places and much more seasonal: dark severe winters, dusty thaw, mosquito-rich green-up, and a brilliant fall that arrives early.", expanded: "Dawson City sits far inland near the Arctic Circle, where winter cold pools along the Yukon River and summer daylight runs long enough to push gardens fast. It is drier than many coastal northern places and much more seasonal: dark severe winters, dusty thaw, mosquito-rich green-up, and a brilliant fall that arrives early. At 320 m, the setting — Yukon River and Klondike River confluence in a cold interior basin under long subarctic daylight — does most of the explanatory work here. Expect summer afternoons near 22°C and winter nights near -26°C as the baseline, with about 316 mm of precipitation across a typical year." },
  "des-moines-ia": { original: "Des Moines sits in America’s most productive corn belt — summer dew points and CAPE build ahead of fronts; winter brings Arctic outbreaks and occasional ice storms.", expanded: "Des Moines sits in America’s most productive corn belt — summer dew points and CAPE build ahead of fronts; winter brings Arctic outbreaks and occasional ice storms. The draw for most visitors is straightforward — state fair — but the climate is what keeps people coming back. Flooding and severe-storm risk are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 920 mm, with summer afternoons averaging near 29°C and winter nights near -9°C — the numbers a scouting trip should actually check." },
  "duluth-mn": { original: "Duluth's elevation above the lake and persistent onshore flow keeps July afternoons cooler than Minneapolis by a wide margin. Winter brings legendary lake-effect snow bands on the South Shore. Spring is slow to arrive — fog and ice linger — but autumn is crisp and brilliant.", expanded: "Duluth's elevation above the lake and persistent onshore flow keeps July afternoons cooler than Minneapolis by a wide margin. Winter brings legendary lake-effect snow bands on the South Shore. Spring is slow to arrive — fog and ice linger — but autumn is crisp and brilliant. Lake effect is doing quiet work behind the numbers, and it is why Duluth does not feel like a generic Dfb town. Expect summer afternoons near 24°C and winter nights near -13°C as the baseline, with about 761 mm of precipitation across a typical year." },
  "durango-co": { original: "Durango sits at 1988 m in the Animas Valley, sheltered between the San Juan peaks to the north and the Mesa Verde country to the south. The valley orientation moderates extremes; winters are mild by Rocky Mountain standards (January mean high around 5°C) and summers stay in the high 20s. Monsoon season brings dramatic afternoon thunderstorms against the peaks.", expanded: "Durango sits at 1988 m in the Animas Valley, sheltered between the San Juan peaks to the north and the Mesa Verde country to the south. The valley orientation moderates extremes; winters are mild by Rocky Mountain standards (January mean high around 5°C) and summers stay in the high 20s. Monsoon season brings dramatic afternoon thunderstorms against the peaks. It suits active retirees more than casual visitors chasing a postcard version of the mild-winter foothills. Wildfire and wildfire smoke are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "durango-mx": { original: "Durango is not tropical Mexico. Its elevation keeps nights crisp, the dry season is bright and dusty, and summer storms build off the Sierra Madre Occidental. The city sits in a broad basin, so stagnant winter mornings and strong day-night swings both belong to the lived climate.", expanded: "Durango is not tropical Mexico. Its elevation keeps nights crisp, the dry season is bright and dusty, and summer storms build off the Sierra Madre Occidental. The city sits in a broad basin, so stagnant winter mornings and strong day-night swings both belong to the lived climate. The honest tradeoff is drought, which runs elevated and worsening and is worth weighing against the mild-sounding averages. Victoria de Durango rewards people who plan around the monsoon-edge zone pattern rather than treating it as scenery. Victoria de Durango sits inside highland semiarid grassland and pine-oak transition, and that biome is as much a product of the local climate as a backdrop to it." },
  "ellensburg-wa": { original: "Ellensburg sits at a classic gap: the Kittitas Valley funnels pressure differences between the wet west side and the dry Columbia Plateau into persistent, often howling wind. Summers are hot-dry-sunny and winters are cold but clearer than west of the crest. The wind is the signature — ranchers joke that the day it stops blowing everyone in town goes to see a doctor.", expanded: "Ellensburg sits at a classic gap: the Kittitas Valley funnels pressure differences between the wet west side and the dry Columbia Plateau into persistent, often howling wind. Summers are hot-dry-sunny and winters are cold but clearer than west of the crest. The wind is the signature — ranchers joke that the day it stops blowing everyone in town goes to see a doctor. The honest tradeoff is wildfire, which runs elevated and worsening and is worth weighing against the mild-sounding averages. Ellensburg rewards people who plan around the rain-shadow sanctuary pattern rather than treating it as scenery." },
  "eminence-mo": { original: "Eminence is the gateway to some of the clearest spring rivers in the Lower 48. Groundwater upwelling holds near-stable temperatures year-round; in summer, paddlers experience cold pools and fog banks at confluences that would not exist in a non-karst landscape. The hills are modest in elevation but enormous in hydrologic complexity.", expanded: "Eminence is the gateway to some of the clearest spring rivers in the Lower 48. Groundwater upwelling holds near-stable temperatures year-round; in summer, paddlers experience cold pools and fog banks at confluences that would not exist in a non-karst landscape. The hills are modest in elevation but enormous in hydrologic complexity. It suits paddlers more than casual visitors chasing a postcard version of the limestone / karst pocket. Flooding and severe-storm risk are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "erie-pa": { original: "Erie receives some of the heaviest snow totals in Pennsylvania when cold air crosses the warm lake. Summer is mild and humid with lake breezes; thunderstorms rake along the lake breeze front. The climate is a hybrid of Midwest continentality and Great Lakes maritime delay.", expanded: "Erie receives some of the heaviest snow totals in Pennsylvania when cold air crosses the warm lake. Summer is mild and humid with lake breezes; thunderstorms rake along the lake breeze front. The climate is a hybrid of Midwest continentality and Great Lakes maritime delay. The rhythm holds most years: summer highs near 26°C, winter lows near -5°C, and about 1146 mm of precipitation overall. The Köppen Dfb label is the broad-stroke summary; the lake-effect snowbelt pattern is the fine-grained read a visit actually delivers. It suits lake-house seekers more than casual visitors chasing a postcard version of the lake-effect snowbelt." },
  "friday-harbor-wa": { original: "The San Juans sit in a complex rain shadow cast by the Olympics and Vancouver Island — enough moisture for pastoral green, but enough summer sun to support vineyards and apple orchards on south slopes. Marine breezes keep August afternoons civilized; frost is rare near shore.", expanded: "The San Juans sit in a complex rain shadow cast by the Olympics and Vancouver Island — enough moisture for pastoral green, but enough summer sun to support vineyards and apple orchards on south slopes. Marine breezes keep August afternoons civilized; frost is rare near shore. The rhythm holds most years: summer highs near 21°C, winter lows near 3°C, and about 646 mm of precipitation overall. Rain shadow is doing quiet work behind the numbers, and it is why Friday Harbor does not feel like a generic Csb town." },
  "galena-il": { original: "Galena’s postcard hills are not decorative; they organize cold drainage, spring phenology, and wind exposure in ways flat corn country cannot. The Mississippi moderates some winter cold but also supplies moisture for lake-effect-like cloud streets when synoptic flow aligns. It is a microclimate laboratory squeezed into a tourist town.", expanded: "Galena’s postcard hills are not decorative; they organize cold drainage, spring phenology, and wind exposure in ways flat corn country cannot. The Mississippi moderates some winter cold but also supplies moisture for lake-effect-like cloud streets when synoptic flow aligns. It is a microclimate laboratory squeezed into a tourist town. The honest tradeoff is flooding, which runs elevated and worsening and is worth weighing against the mild-sounding averages. Galena rewards people who plan around the driftless relief pocket pattern rather than treating it as scenery. Galena sits inside oak savanna and prairie openings, and that biome is as much a product of the local climate as a backdrop to it." },
  "gaspe-qc": { original: "The Gaspé's eastern tip plunges into the Gulf of St. Lawrence, which is cold for much of the year. Summers stay cool and frequently foggy; winter is long and stormy with wind-driven snow. The maritime modification softens what at 48° latitude inland would be brutally continental — making this one of Eastern Canada's most dramatic land-sea climate transitions.", expanded: "The Gaspé's eastern tip plunges into the Gulf of St. Lawrence, which is cold for much of the year. Summers stay cool and frequently foggy; winter is long and stormy with wind-driven snow. The maritime modification softens what at 48° latitude inland would be brutally continental — making this one of Eastern Canada's most dramatic land-sea climate transitions. The rhythm holds most years: summer highs near 20°C, winter lows near -12°C, and about 1203 mm of precipitation overall. Marine layer is doing quiet work behind the numbers, and it is why Gaspé does not feel like a generic Dfb town." },
  "gatlinburg-tn": { original: "Gatlinburg sits at the interface of tourist strip and national park rainforest. Orographic lifting on the Smokies produces abundant rainfall and persistent fog on cool mornings; elevation gradients mean wildflower and fall-color seasons are long and stratified by slope aspect.", expanded: "Gatlinburg sits at the interface of tourist strip and national park rainforest. Orographic lifting on the Smokies produces abundant rainfall and persistent fog on cool mornings; elevation gradients mean wildflower and fall-color seasons are long and stratified by slope aspect. The honest tradeoff is flooding, which runs elevated and worsening and is worth weighing against the mild-sounding averages. It suits hospitality workers more than casual visitors chasing a postcard version of the thermal belt. At 390 m, the setting — Tourism gateway on the West Fork of the Little Pigeon River — does most of the explanatory work here." },
  "geneva-on-the-lake-oh": { original: "Geneva-on-the-Lake inherits the full Great Lakes curriculum: delayed leaf-out, abundant winter cloud, and sharp mesoscale snow bands that can bury the strip while Columbus stays dry. Summer is warm and humid with lake breezes; thunderstorms propagate along lake-outflow boundaries.", expanded: "Geneva-on-the-Lake inherits the full Great Lakes curriculum: delayed leaf-out, abundant winter cloud, and sharp mesoscale snow bands that can bury the strip while Columbus stays dry. Summer is warm and humid with lake breezes; thunderstorms propagate along lake-outflow boundaries. At 185 m, the setting — Lake Erie shoreline east of Cleveland where westerly flow produces long-fetch lake-effect streamers — does most of the explanatory work here. Expect summer afternoons near 27°C and winter nights near -5°C as the baseline, with about 1068 mm of precipitation across a typical year." },
  "grand-manan-nb": { original: "Twelve-meter Fundy tides cycle enormous volumes of cold water past the island, producing a dramatically moderated maritime climate: cool wet summers, mild winters, relentless fog, and a salt-scrubbed plant community.", expanded: "Twelve-meter Fundy tides cycle enormous volumes of cold water past the island, producing a dramatically moderated maritime climate: cool wet summers, mild winters, relentless fog, and a salt-scrubbed plant community. The rhythm holds most years: summer highs near 22°C, winter lows near -8°C, and about 1342 mm of precipitation overall. The Köppen Dfb label is the broad-stroke summary; the hyper-maritime pattern is the fine-grained read a visit actually delivers. It suits hardy maritime families more than casual visitors chasing a postcard version of the hyper-maritime. Severe-storm risk and coastal storm-surge risk are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "grand-marais-mi": { original: "Winter winds cross 300 km of open Lake Superior before reaching this sandy shore, dumping colossal snow totals. Summers are short, cool, and exquisite; winters are defining. Communities along the Grand Marais–Munising shore measure snow in meters, not centimeters.", expanded: "Winter winds cross 300 km of open Lake Superior before reaching this sandy shore, dumping colossal snow totals. Summers are short, cool, and exquisite; winters are defining. Communities along the Grand Marais–Munising shore measure snow in meters, not centimeters. The rhythm holds most years: summer highs near 23°C, winter lows near -10°C, and about 924 mm of precipitation overall. Grand Marais sits inside northern hardwood-boreal, and that biome is as much a product of the local climate as a backdrop to it. It suits serious winter lovers more than casual visitors chasing a postcard version of the lake-effect snowbelt." },
  "guanajuato-mx": { original: "Guanajuato is built into a steep canyon at 2000 m in the Sierra de Guanajuato. Its geography produces fascinating microclimate variation along the canyon walls — sun-facing slopes warm quickly while shaded ones stay cool. The general climate is cool-dry eternal-spring: afternoon highs 22–27°C, dry most of the year with a June–September rainy season. The colorful terraced houses catch the high-altitude sun from every angle.", expanded: "Guanajuato is built into a steep canyon at 2000 m in the Sierra de Guanajuato. Its geography produces fascinating microclimate variation along the canyon walls — sun-facing slopes warm quickly while shaded ones stay cool. The general climate is cool-dry eternal-spring: afternoon highs 22–27°C, dry most of the year with a June–September rainy season. The colorful terraced houses catch the high-altitude sun from every angle. It suits cultural expats more than casual visitors chasing a postcard version of the eternal-spring highland. Day-to-day life here means paying attention to seasonal extremes, not just the annual averages." },
  "halifax-ns": { original: "Halifax mixes Gulf Stream–influenced mild winters with foggy springs and crisp autumns. Summer heat is moderated by onshore flow; winter snowfall is modest but blizzards can roar off the Atlantic. Hurricane remnants occasionally bring heavy rain.", expanded: "Halifax mixes Gulf Stream–influenced mild winters with foggy springs and crisp autumns. Summer heat is moderated by onshore flow; winter snowfall is modest but blizzards can roar off the Atlantic. Hurricane remnants occasionally bring heavy rain. The rhythm holds most years: summer highs near 22°C, winter lows near -6°C, and about 1449 mm of precipitation overall. Halifax sits inside Acadian mixed forest, and that biome is as much a product of the local climate as a backdrop to it. Halifax rewards people who plan around the cool-summer maritime pattern rather than treating it as scenery." },
  "hermosillo-mx": { original: "Hermosillo is core desert: triple-digit afternoon heat indices for months, cooling at night when skies clear. July–August storms bring drama — virga, dust, localized downpours — but annual totals stay low. Winter is the pleasant season outsiders underestimate.", expanded: "Hermosillo is core desert: triple-digit afternoon heat indices for months, cooling at night when skies clear. July–August storms bring drama — virga, dust, localized downpours — but annual totals stay low. Winter is the pleasant season outsiders underestimate. The honest tradeoff is extreme summer heat, which runs very-high and worsening and is worth weighing against the mild-sounding averages. The draw for most visitors is straightforward — Bahía de Kino day trips — but the climate is what keeps people coming back. Continental extremity is doing quiet work behind the numbers, and it is why Hermosillo does not feel like a generic BWh town." },
  "honolulu-hi": { original: "Honolulu sits where trades split around topography; Waianae range shadows produce west-side dryness while Hilo-like rainfall stays windward. Urban heat island elevates minima in the core.", expanded: "Honolulu sits where trades split around topography; Waianae range shadows produce west-side dryness while Hilo-like rainfall stays windward. Urban heat island elevates minima in the core. Trade-wind regime is doing quiet work behind the numbers, and it is why Honolulu does not feel like a generic As town. Expect summer afternoons near 30°C and winter nights near 19°C as the baseline, with about 1104 mm of precipitation across a typical year. The honest tradeoff is coastal storm-surge risk, which runs high and worsening and is worth weighing against the mild-sounding averages." },
  "hood-river-gorge": { original: "The Columbia Gorge is one of the world's great natural wind tunnels: the only sea-level gap through a major mountain range. West-to-east, it channels marine air inland, and east-to-west, it channels desert dryness outward — with the resulting pressure gradient producing the world-famous windsurfing winds. The climate transects here are staggering: from moss-dripping rainforest at Bonneville to sagebrush steppe 80 km east at The Dalles.", expanded: "The Columbia Gorge is one of the world's great natural wind tunnels: the only sea-level gap through a major mountain range. West-to-east, it channels marine air inland, and east-to-west, it channels desert dryness outward — with the resulting pressure gradient producing the world-famous windsurfing winds. The climate transects here are staggering: from moss-dripping rainforest at Bonneville to sagebrush steppe 80 km east at The Dalles. The Köppen Csb label is the broad-stroke summary; the gap / gorge wind corridor pattern is the fine-grained read a visit actually delivers." },
  "houghton-mi": { original: "The Keweenaw thrusts 100 km into Lake Superior, exposing it to lake-effect snow from nearly every wind direction. Annual snowfall averages 5 m near Houghton and approaches 7 m on the peninsula's spine. The copper-mining history, the university at Michigan Tech, and the culture of the place are all shaped by the snow. Summers, by contrast, are idyllic: mild, breezy, and sun-sparkled.", expanded: "The Keweenaw thrusts 100 km into Lake Superior, exposing it to lake-effect snow from nearly every wind direction. Annual snowfall averages 5 m near Houghton and approaches 7 m on the peninsula's spine. The copper-mining history, the university at Michigan Tech, and the culture of the place are all shaped by the snow. Summers, by contrast, are idyllic: mild, breezy, and sun-sparkled. Houghton rewards people who plan around the lake-effect snowbelt pattern rather than treating it as scenery. Extreme winter cold and severe-storm risk are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "international-falls-mn": { original: "International Falls anchors the border climate where Arctic air masses arrive unimpeded and winter nights routinely plunge far below freezing. Summer is brief but surprisingly pleasant — warm days, cool nights, long evening light. Lake-effect snow and lake ice modulate the harshest extremes slightly, but not enough to soften the reputation.", expanded: "International Falls anchors the border climate where Arctic air masses arrive unimpeded and winter nights routinely plunge far below freezing. Summer is brief but surprisingly pleasant — warm days, cool nights, long evening light. Lake-effect snow and lake ice modulate the harshest extremes slightly, but not enough to soften the reputation. International Falls rewards people who plan around the cold-air pool pattern rather than treating it as scenery. Day-to-day life here means paying attention to seasonal extremes, not just the annual averages. Annual precipitation runs close to 704 mm, with summer afternoons averaging near 25°C and winter nights near -18°C — the numbers a scouting trip should actually check." },
  "jackson-wy": { original: "Jackson Hole traps cold air and captures Pacific moisture lifted by the Tetons; snowpack feeds the Snake River system that defines the ecosystem.", expanded: "Jackson Hole traps cold air and captures Pacific moisture lifted by the Tetons; snowpack feeds the Snake River system that defines the ecosystem. The Köppen Dfc label is the broad-stroke summary; the cold-air pool pattern is the fine-grained read a visit actually delivers. Expect summer afternoons near 25°C and winter nights near -13°C as the baseline, with about 610 mm of precipitation across a typical year. The honest tradeoff is wildfire, which runs elevated and worsening and is worth weighing against the mild-sounding averages. The draw for most visitors is straightforward — Grand Teton NP — but the climate is what keeps people coming back." },
  "joseph-or": { original: "The Wallowas rise 3000 m from broad glacial valleys in Oregon's remote northeast. Joseph and Enterprise sit in the Wallowa Valley at 1292 m — high, dry, sunny, and sheltered from both Pacific storms and the worst of Rocky Mountain cold. Summers are warm-dry-brilliant, winters bring reliable snow but without deep-cold continental intensity. The valley's ranching character is visible and the scenery is Alpine in both senses.", expanded: "The Wallowas rise 3000 m from broad glacial valleys in Oregon's remote northeast. Joseph and Enterprise sit in the Wallowa Valley at 1292 m — high, dry, sunny, and sheltered from both Pacific storms and the worst of Rocky Mountain cold. Summers are warm-dry-brilliant, winters bring reliable snow but without deep-cold continental intensity. The valley's ranching character is visible and the scenery is Alpine in both senses. The rhythm holds most years: summer highs near 26°C, winter lows near -6°C, and about 589 mm of precipitation overall. At 1292 m, the setting — Wallowa Valley at the foot of the Wallowa Mountains — the 'Alps of Oregon' in the state's remote northeast — does most of the explanatory work here." },
  "kamloops-bc": { original: "Kamloops sits at the confluence of the North and South Thompson rivers in the deep Coast-Mountains rain shadow. Annual precipitation averages under 300 mm. Summer afternoons push into the 33–36°C range; the hillsides are sagebrush, bunchgrass, and ponderosa pine. Winters are cold-sunny and drier than elsewhere at the latitude. It's Canada's most American-Southwest-feeling small city.", expanded: "Kamloops sits at the confluence of the North and South Thompson rivers in the deep Coast-Mountains rain shadow. Annual precipitation averages under 300 mm. Summer afternoons push into the 33–36°C range; the hillsides are sagebrush, bunchgrass, and ponderosa pine. Winters are cold-sunny and drier than elsewhere at the latitude. It's Canada's most American-Southwest-feeling small city. The honest tradeoff is wildfire, which runs high and worsening and is worth weighing against the mild-sounding averages. The draw for most visitors is straightforward — desert hiking — but the climate is what keeps people coming back." },
  "kelowna-bc": { original: "Kelowna combines interior sunshine with lake thermal inertia: July afternoons are warm enough for Syrah and Merlot, but lake breezes knock the edge off heat domes. Winter inversions trap smog and moisture in the valley; spring frost fights are a viticulture ritual.", expanded: "Kelowna combines interior sunshine with lake thermal inertia: July afternoons are warm enough for Syrah and Merlot, but lake breezes knock the edge off heat domes. Winter inversions trap smog and moisture in the valley; spring frost fights are a viticulture ritual. It suits viticulture workers more than casual visitors chasing a postcard version of the rain-shadow sanctuary. Wildfire and wildfire smoke are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 346 mm, with summer afternoons averaging near 28°C and winter nights near -3°C — the numbers a scouting trip should actually check." },
  "la-paz-mx": { original: "La Paz sits on a sheltered bay of the Sea of Cortez, where the desert coast meets some of the world's clearest water. Winters are nearly ideal — 26°C days, 14°C nights, constant sun. Summers are brutal: 35°C afternoons, humidity rising in the wet season, and hurricane season from August through October. The warm Cortez moderates summer heat compared to the interior but raises humidity.", expanded: "La Paz sits on a sheltered bay of the Sea of Cortez, where the desert coast meets some of the world's clearest water. Winters are nearly ideal — 26°C days, 14°C nights, constant sun. Summers are brutal: 35°C afternoons, humidity rising in the wet season, and hurricane season from August through October. The warm Cortez moderates summer heat compared to the interior but raises humidity. The rhythm holds most years: summer highs near 37°C, winter lows near 12°C, and about 162 mm of precipitation overall. At 10 m, the setting — Sheltered Bahía de La Paz on the Sea of Cortez side of Baja Sur — does most of the explanatory work here." },
  "leamington-on": { original: "Leamington sits at 42° latitude — south of the northern California border — on Lake Erie's north shore. The combination of low latitude and lake moderation produces Canada's longest frost-free season (~180 days) and warmest summers. The town has been the country's tomato-growing capital for generations; massive greenhouse complexes now dominate, leveraging both the climate and lake-sourced cooling/heating.", expanded: "Leamington sits at 42° latitude — south of the northern California border — on Lake Erie's north shore. The combination of low latitude and lake moderation produces Canada's longest frost-free season (~180 days) and warmest summers. The town has been the country's tomato-growing capital for generations; massive greenhouse complexes now dominate, leveraging both the climate and lake-sourced cooling/heating. The honest tradeoff is severe-storm risk, which runs elevated and worsening and is worth weighing against the mild-sounding averages. It suits greenhouse farmers more than casual visitors chasing a postcard version of the lake-moderated." },
  "leavenworth-wa": { original: "Leavenworth combines Cascade scenery with continental seasonality: summer heat breaks 30°C regularly; winter snow is reliable for recreation. Chinooks occasionally chew snowpack in midwinter. Irrigation from the Wenatchee supports apples and pears that need winter chill.", expanded: "Leavenworth combines Cascade scenery with continental seasonality: summer heat breaks 30°C regularly; winter snow is reliable for recreation. Chinooks occasionally chew snowpack in midwinter. Irrigation from the Wenatchee supports apples and pears that need winter chill. The honest tradeoff is wildfire, which runs high and worsening and is worth weighing against the mild-sounding averages. The draw for most visitors is straightforward — Oktoberfest — but the climate is what keeps people coming back. The Köppen Dsa label is the broad-stroke summary; the rain-shadow sanctuary pattern is the fine-grained read a visit actually delivers." },
  "lewes-de": { original: "Lewes sits where the bay’s huge tidal prism organizes daily wind: onshore flow on warm afternoons, land breezes at night, and periodic nor’easters that reshape coastal dunes. It lacks the elevation microclimates of the Appalachians but exemplifies estuarine moderation in a mostly flat state.", expanded: "Lewes sits where the bay’s huge tidal prism organizes daily wind: onshore flow on warm afternoons, land breezes at night, and periodic nor’easters that reshape coastal dunes. It lacks the elevation microclimates of the Appalachians but exemplifies estuarine moderation in a mostly flat state. The honest tradeoff is coastal storm-surge risk, which runs high and worsening and is worth weighing against the mild-sounding averages. It suits coastal retirees more than casual visitors chasing a postcard version of the lake-moderated. Lewes sits inside maritime forest and salt marsh edge, and that biome is as much a product of the local climate as a backdrop to it." },
  "lone-pine-ca": { original: "Lone Pine lives in the hydraulic shadow of the Sierra: dry, windy, and often hazy from Owens Lake dust and seasonal smoke. Winter cold pools in the valley; summer convection builds over the peaks while the floor bakes. It is the gateway climate for Whitney Portal — a vertical kilometer of lapse-rate cooling in minutes of driving.", expanded: "Lone Pine lives in the hydraulic shadow of the Sierra: dry, windy, and often hazy from Owens Lake dust and seasonal smoke. Winter cold pools in the valley; summer convection builds over the peaks while the floor bakes. It is the gateway climate for Whitney Portal — a vertical kilometer of lapse-rate cooling in minutes of driving. The honest tradeoff is drought, which runs high and worsening and is worth weighing against the mild-sounding averages. The draw for most visitors is straightforward — Alabama Hills — but the climate is what keeps people coming back." },
  "lubbock-tx": { original: "Lubbock sits on the Llano Estacado where summer afternoons routinely top 35°C and humidity drops into the teens. Spring brings dryline thunderstorms and occasional dust storms. Winter is sunny and mild by northern standards but punctuated by blue northers.", expanded: "Lubbock sits on the Llano Estacado where summer afternoons routinely top 35°C and humidity drops into the teens. Spring brings dryline thunderstorms and occasional dust storms. Winter is sunny and mild by northern standards but punctuated by blue northers. The rhythm holds most years: summer highs near 34°C, winter lows near -2°C, and about 488 mm of precipitation overall. Continental extremity is the mechanism, layering a badland / steppe pocket pattern onto the BSk-class averages a map alone would suggest. Lubbock rewards people who plan around the badland / steppe pocket pattern rather than treating it as scenery." },
  "mammoth-lakes-ca": { original: "Mammoth sits at 2424 m on the east side of the Sierra crest where storms deposit their snow before descending to the Owens Valley rain shadow. The climate is subalpine — 30 inches of water equivalent in an average winter, 300+ sunny days, intense UV, and summer afternoons that rarely exceed 25°C. The volcanic geology (still an active caldera) adds geothermal features that shape local micro-microclimates.", expanded: "Mammoth sits at 2424 m on the east side of the Sierra crest where storms deposit their snow before descending to the Owens Valley rain shadow. The climate is subalpine — 30 inches of water equivalent in an average winter, 300+ sunny days, intense UV, and summer afternoons that rarely exceed 25°C. The volcanic geology (still an active caldera) adds geothermal features that shape local micro-microclimates. It suits ski bums more than casual visitors chasing a postcard version of the alpine tundra. Extreme winter cold and wildfire smoke are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "mazamitla-mx": { original: "Mazamitla sits at 2220 m in the Sierra del Tigre. The climate is cool year-round; winter nights can approach freezing, summer afternoons rarely exceed 22°C.", expanded: "Mazamitla sits at 2220 m in the Sierra del Tigre. The climate is cool year-round; winter nights can approach freezing, summer afternoons rarely exceed 22°C. Elevation lapse rate is the mechanism, layering a eternal-spring highland pattern onto the Cwb-class averages a map alone would suggest. Expect summer afternoons near 25°C and winter nights near 5°C as the baseline, with about 897 mm of precipitation across a typical year. No single hazard dominates the risk picture here, which is itself part of the appeal. Mazamitla rewards people who plan around the eternal-spring highland pattern rather than treating it as scenery." },
  "mazatlan-mx": { original: "Mazatlán delivers postcard winters and steamy summers when the ITCZ influence returns. Pacific storms occasionally send swell and humidity; inland sierras wring rain that rarely reaches the beach uniformly.", expanded: "Mazatlán delivers postcard winters and steamy summers when the ITCZ influence returns. Pacific storms occasionally send swell and humidity; inland sierras wring rain that rarely reaches the beach uniformly. The honest tradeoff is severe-storm risk, which runs very-high and worsening and is worth weighing against the mild-sounding averages. The draw for most visitors is straightforward — historic centro — but the climate is what keeps people coming back. Mazatlán sits inside tropical savanna and coastal mangrove margin, and that biome is as much a product of the local climate as a backdrop to it." },
  "medford-or": { original: "Medford sits in a classic inter-mountain rain shadow: the Coast Range and Klamaths wring out Pacific moisture west and north, leaving the Rogue Basin with sunny, arid summers that feel more Central Valley than Portland. Winter inversions trap smoke and fog in the bowl; spring arrives abruptly with blossom corridors along irrigation canals.", expanded: "Medford sits in a classic inter-mountain rain shadow: the Coast Range and Klamaths wring out Pacific moisture west and north, leaving the Rogue Basin with sunny, arid summers that feel more Central Valley than Portland. Winter inversions trap smoke and fog in the bowl; spring arrives abruptly with blossom corridors along irrigation canals. The rhythm holds most years: summer highs near 32°C, winter lows near 0°C, and about 553 mm of precipitation overall. The Köppen Csa label is the broad-stroke summary; the rain-shadow sanctuary pattern is the fine-grained read a visit actually delivers." },
  "mentone-al": { original: "Mentone sits on the same Appalachian escarpment that runs into Georgia and Tennessee, but here the state’s stereotypical swelter finally breaks. Westerly storm systems ride the plateau edge; thermal belts and coves on the scarp produce sharp spring frost contrasts that orchardists still map by hand. It is one of the few places in Alabama where true four-season gardening feels honest.", expanded: "Mentone sits on the same Appalachian escarpment that runs into Georgia and Tennessee, but here the state’s stereotypical swelter finally breaks. Westerly storm systems ride the plateau edge; thermal belts and coves on the scarp produce sharp spring frost contrasts that orchardists still map by hand. It is one of the few places in Alabama where true four-season gardening feels honest. At 548 m, the setting — Village on the Cumberland Plateau / Lookout Mountain scarp — roughly 550 m above the Tennessee Valley floor to the west — does most of the explanatory work here." },
  "merida-mx": { original: "Mérida sits on the Yucatán's flat limestone plateau, where cenotes (collapsed karst sinkholes) provide the region's only surface water. Winters are warm-dry-sunny (highs 30°C, low humidity); summers are hotter and humid with afternoon downpours from May through October. Hurricane exposure is real but the inland position dampens the worst direct impacts compared to Cancún or Campeche on the coast.", expanded: "Mérida sits on the Yucatán's flat limestone plateau, where cenotes (collapsed karst sinkholes) provide the region's only surface water. Winters are warm-dry-sunny (highs 30°C, low humidity); summers are hotter and humid with afternoon downpours from May through October. Hurricane exposure is real but the inland position dampens the worst direct impacts compared to Cancún or Campeche on the coast. Karst infiltration is doing quiet work behind the numbers, and it is why Mérida does not feel like a generic Aw town. Expect summer afternoons near 34°C and winter nights near 17°C as the baseline, with about 961 mm of precipitation across a typical year." },
  "missoula-mt": { original: "Missoula's geometry — a broad valley ringed by mountains, five rivers converging, frequent calm high-pressure winter weather — produces reliable, stubborn inversions. On the worst weeks, stagnant cold air fills the valley to 400 m depth while ridgetops bask in sun 15°C warmer. Smoke events amplify the stagnation. Summers, by contrast, are warm, sunny, and smoke-smudged increasingly often as fires climb nearby canyons.", expanded: "Missoula's geometry — a broad valley ringed by mountains, five rivers converging, frequent calm high-pressure winter weather — produces reliable, stubborn inversions. On the worst weeks, stagnant cold air fills the valley to 400 m depth while ridgetops bask in sun 15°C warmer. Smoke events amplify the stagnation. Summers, by contrast, are warm, sunny, and smoke-smudged increasingly often as fires climb nearby canyons. The rhythm holds most years: summer highs near 28°C, winter lows near -7°C, and about 416 mm of precipitation overall. Temperature inversion is doing quiet work behind the numbers, and it is why Missoula does not feel like a generic Dfb town." },
  "moab-ut": { original: "Moab sits at 1245 m in a canyon carved by the Colorado River, walled by red-rock cliffs that radiate heat. Summer afternoons regularly top 38°C. But the same canyon walls shelter winter: January averages 8°C, much warmer than the Colorado Plateau above. Spring and fall are the true glory — warm days, cool nights, an unbeatable rock-climbing climate.", expanded: "Moab sits at 1245 m in a canyon carved by the Colorado River, walled by red-rock cliffs that radiate heat. Summer afternoons regularly top 38°C. But the same canyon walls shelter winter: January averages 8°C, much warmer than the Colorado Plateau above. Spring and fall are the true glory — warm days, cool nights, an unbeatable rock-climbing climate. Moab rewards people who plan around the desert oasis pattern rather than treating it as scenery. Drought and extreme summer heat are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "mobile-al": { original: "Mobile receives abundant rainfall from Gulf of Mexico moisture streams; sea breezes clash with interior heat to build summer convection. Tropical systems can deliver extreme multi-day rains.", expanded: "Mobile receives abundant rainfall from Gulf of Mexico moisture streams; sea breezes clash with interior heat to build summer convection. Tropical systems can deliver extreme multi-day rains. The honest tradeoff is severe-storm risk, which runs very-high and worsening and is worth weighing against the mild-sounding averages. Mobile rewards people who plan around the hurricane-exposed coast pattern rather than treating it as scenery. At 3 m, the setting — Mobile Bay and Mississippi Sound — warm shelf water and frequent Gulf moisture influx — does most of the explanatory work here." },
  "monterrey-mx": { original: "Monterrey mixes high-insolation semi-arid baseline with summer convection that builds against the eastern sierra. Urban expansion amplifies nocturnal heat; industrial air quality interacts with basin geometry. When Gulf moisture taps in, thunderstorms can drop localized hail.", expanded: "Monterrey mixes high-insolation semi-arid baseline with summer convection that builds against the eastern sierra. Urban expansion amplifies nocturnal heat; industrial air quality interacts with basin geometry. When Gulf moisture taps in, thunderstorms can drop localized hail. Monterrey rewards people who plan around the monsoon-edge zone pattern rather than treating it as scenery. Extreme summer heat and flooding are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 475 mm, with summer afternoons averaging near 36°C and winter nights near 8°C — the numbers a scouting trip should actually check." },
  "morden-mb": { original: "Morden sits in one of Manitoba's warmer growing-season pockets, close to the Pembina Escarpment and the dry western edge of the Red River lowland. Summers can be hot enough for corn, grapes, and long-season gardens; winters are still fully prairie. The microclimate value lies in heat units and sun, not mildness.", expanded: "Morden sits in one of Manitoba's warmer growing-season pockets, close to the Pembina Escarpment and the dry western edge of the Red River lowland. Summers can be hot enough for corn, grapes, and long-season gardens; winters are still fully prairie. The microclimate value lies in heat units and sun, not mildness. The draw for most visitors is straightforward — Morden research station heritage — but the climate is what keeps people coming back. Extreme winter cold and drought are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "morelia-mx": { original: "Morelia sits at 1920 m in the Bajío highlands. Temperatures stay within a narrow band year-round: afternoon highs 24–28°C, nights 7–13°C. The climate is defined not by temperature swings but by the rainy season — June through September delivers dramatic afternoon thunderstorms; the rest of the year is bone-dry and brilliantly sunny. The colonial cantera-pink stone architecture glows in that high-altitude light.", expanded: "Morelia sits at 1920 m in the Bajío highlands. Temperatures stay within a narrow band year-round: afternoon highs 24–28°C, nights 7–13°C. The climate is defined not by temperature swings but by the rainy season — June through September delivers dramatic afternoon thunderstorms; the rest of the year is bone-dry and brilliantly sunny. The colonial cantera-pink stone architecture glows in that high-altitude light. It suits Latin-American urbanites more than casual visitors chasing a postcard version of the eternal-spring highland. Day-to-day life here means paying attention to seasonal extremes, not just the annual averages." },
  "morgantown-wv": { original: "Morgantown’s ridges catch moisture on southwesterly flow ahead of coastal lows; valleys pool cold air and fog on still nights. Snowfall is moderate but elevation within the county varies enough for 200 m to separate rain from heavy snow. Summers are warm and humid — not coastal, not deep South, but persistently sticky. The university town sits at a climate crossroads between mid-Atlantic storms and Ohio Valley convection.", expanded: "Morgantown’s ridges catch moisture on southwesterly flow ahead of coastal lows; valleys pool cold air and fog on still nights. Snowfall is moderate but elevation within the county varies enough for 200 m to separate rain from heavy snow. Summers are warm and humid — not coastal, not deep South, but persistently sticky. The university town sits at a climate crossroads between mid-Atlantic storms and Ohio Valley convection. At 273 m, the setting — Dissected Allegheny Plateau — does most of the explanatory work here. Expect summer afternoons near 28°C and winter nights near -4°C as the baseline, with about 1198 mm of precipitation across a typical year." },
  "mount-charleston-nv": { original: "The Spring Mountains rise abruptly from the basin floor where subsidence and dryness dominate. Upslope flow brings cloud and occasional thunderstorms; winter storms deliver real snowpack. The inversion that traps smog and heat below also isolates the high elevations as a climatic refuge — a pattern documented in mountain–basin meteorology worldwide.", expanded: "The Spring Mountains rise abruptly from the basin floor where subsidence and dryness dominate. Upslope flow brings cloud and occasional thunderstorms; winter storms deliver real snowpack. The inversion that traps smog and heat below also isolates the high elevations as a climatic refuge — a pattern documented in mountain–basin meteorology worldwide. The Köppen Dsb label is the broad-stroke summary; the sky-island refuge pattern is the fine-grained read a visit actually delivers. Expect summer afternoons near 25°C and winter nights near -5°C as the baseline, with about 517 mm of precipitation across a typical year." },
  "mystic-ct": { original: "Mystic’s climate is paced by water: fog, drizzle, and moderate summer heat. Tropical systems occasionally brush the coast with surge and wind.", expanded: "Mystic’s climate is paced by water: fog, drizzle, and moderate summer heat. Tropical systems occasionally brush the coast with surge and wind. The rhythm holds most years: summer highs near 26°C, winter lows near -4°C, and about 1204 mm of precipitation overall. At 3 m, the setting — Estuarine village between Long Island Sound and Block Island Sound — persistent maritime air — does most of the explanatory work here. The draw for most visitors is straightforward — seaport museum — but the climate is what keeps people coming back." },
  "nags-head-nc": { original: "The Outer Banks are a lesson in exposure: sea breezes cap summer heat, but humidity stays high; winter storms can overwash Highway 12. Each town along the strand has micro-differences in dune height and fetch that matter during storms.", expanded: "The Outer Banks are a lesson in exposure: sea breezes cap summer heat, but humidity stays high; winter storms can overwash Highway 12. Each town along the strand has micro-differences in dune height and fetch that matter during storms. Nags Head sits inside maritime scrub and dune grassland, and that biome is as much a product of the local climate as a backdrop to it. Expect summer afternoons near 30°C and winter nights near 4°C as the baseline, with about 1418 mm of precipitation across a typical year." },
  "napa-ca": { original: "The valley floor heats by day; cool air drains from the Petaluma Gap and marine layer spills east, wrapping benchlands in fog until mid-morning. Bench elevation differences of only tens of meters reorder frost risk and hang time — the entire AVA system is a map of microclimate.", expanded: "The valley floor heats by day; cool air drains from the Petaluma Gap and marine layer spills east, wrapping benchlands in fog until mid-morning. Bench elevation differences of only tens of meters reorder frost risk and hang time — the entire AVA system is a map of microclimate. Napa rewards people who plan around the mediterranean pocket pattern rather than treating it as scenery. Wildfire and drought are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 700 mm, with summer afternoons averaging near 30°C and winter nights near 4°C — the numbers a scouting trip should actually check." },
  "naples-fl": { original: "Naples trades Atlantic surf for Gulf shallows: water temperatures seasonally warm, supporting humid tropical-feeling nights. Cold fronts are brief; sea breezes organize summer convection inland.", expanded: "Naples trades Atlantic surf for Gulf shallows: water temperatures seasonally warm, supporting humid tropical-feeling nights. Cold fronts are brief; sea breezes organize summer convection inland. The Köppen Aw label is the broad-stroke summary; the hurricane-exposed coast pattern is the fine-grained read a visit actually delivers. Expect summer afternoons near 33°C and winter nights near 14°C as the baseline, with about 1477 mm of precipitation across a typical year. The honest tradeoff is flooding, which runs very-high and worsening and is worth weighing against the mild-sounding averages. Naples rewards people who plan around the hurricane-exposed coast pattern rather than treating it as scenery." },
  "nelson-bc": { original: "Nelson perches on the north arm of Kootenay Lake, whose 150-km length and 150-m depth provides substantial thermal moderation to the surrounding steep mountain town. Winters are milder and summers cooler than you'd expect at 49° latitude and 535 m elevation. The arts and counter-culture character traces partly to the mild mountain climate — livable year-round in a way that many Rocky Mountain interior towns are not.", expanded: "Nelson perches on the north arm of Kootenay Lake, whose 150-km length and 150-m depth provides substantial thermal moderation to the surrounding steep mountain town. Winters are milder and summers cooler than you'd expect at 49° latitude and 535 m elevation. The arts and counter-culture character traces partly to the mild mountain climate — livable year-round in a way that many Rocky Mountain interior towns are not. It suits mountain-arts community more than casual visitors chasing a postcard version of the lake-moderated. Wildfire smoke and wildfire are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "new-orleans-la": { original: "New Orleans is a climate of extremes in humidity: summer heat indices routinely exceed 40°C equivalent; thunderstorms pop on summer afternoons; winter cold snaps are short but can freeze citrus on the North Shore. Hurricane risk is existential to infrastructure.", expanded: "New Orleans is a climate of extremes in humidity: summer heat indices routinely exceed 40°C equivalent; thunderstorms pop on summer afternoons; winter cold snaps are short but can freeze citrus on the North Shore. Hurricane risk is existential to infrastructure. The draw for most visitors is straightforward — jazz — but the climate is what keeps people coming back. Flooding and severe-storm risk are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 1740 mm, with summer afternoons averaging near 33°C and winter nights near 8°C — the numbers a scouting trip should actually check." },
  "niagara-on-the-lake": { original: "The Niagara Peninsula is a textbook case of lake moderation plus orographic shelter. Lake Ontario moderates temperature in both directions; the Niagara Escarpment shelters the narrow band of fruit country below from cold air drainage off the Canadian Shield. Winters are mild by Ontario standards; summers are warm and humid; the grape and tender-fruit industries flourish.", expanded: "The Niagara Peninsula is a textbook case of lake moderation plus orographic shelter. Lake Ontario moderates temperature in both directions; the Niagara Escarpment shelters the narrow band of fruit country below from cold air drainage off the Canadian Shield. Winters are mild by Ontario standards; summers are warm and humid; the grape and tender-fruit industries flourish. It suits winemakers more than casual visitors chasing a postcard version of the orchard valley. Day-to-day life here means paying attention to seasonal extremes, not just the annual averages. Annual precipitation runs close to 806 mm, with summer afternoons averaging near 26°C and winter nights near -5°C — the numbers a scouting trip should actually check." },
  "norfolk-ct": { original: "Norfolk collects cold air on clear nights the way a bowl collects water. Lake-effect streamers from Lake Ontario occasionally reach this far southeast when flow aligns; more often it is simply elevation and rural exposure. Summers are mild and short; the town is a cultural bridge between New England ski country and the Hudson Valley.", expanded: "Norfolk collects cold air on clear nights the way a bowl collects water. Lake-effect streamers from Lake Ontario occasionally reach this far southeast when flow aligns; more often it is simply elevation and rural exposure. Summers are mild and short; the town is a cultural bridge between New England ski country and the Hudson Valley. The rhythm holds most years: summer highs near 25°C, winter lows near -9°C, and about 1472 mm of precipitation overall. Cold-air drainage is doing quiet work behind the numbers, and it is why Norfolk does not feel like a generic Dfb town." },
  "oakland-md": { original: "Oakland is the anchor of Garrett County, where Pittsburgh television markets and lake-effect snow belts overlap. Deep Creek Lake adds local moisture and modifies breezes; ridges catch upslope snow on northwesterly flow. Summer is mild and prized by Mid-Atlantic escapees; spring is late and fickle for growers.", expanded: "Oakland is the anchor of Garrett County, where Pittsburgh television markets and lake-effect snow belts overlap. Deep Creek Lake adds local moisture and modifies breezes; ridges catch upslope snow on northwesterly flow. Summer is mild and prized by Mid-Atlantic escapees; spring is late and fickle for growers. Oakland sits inside northern hardwoods and hay meadows, and that biome is as much a product of the local climate as a backdrop to it. Expect summer afternoons near 25°C and winter nights near -6°C as the baseline, with about 1412 mm of precipitation across a typical year." },
  "ocean-springs-ms": { original: "Ocean Springs inherits the same humid subtropical core as the Deep South, but the Sound’s daily heat capacity knocks a few degrees off afternoon peaks relative to inland Hattiesburg. Summer nights stay warm; winter cold fronts are brief and often moderated by returning onshore flow. It is not a dry climate — it is a maritime one.", expanded: "Ocean Springs inherits the same humid subtropical core as the Deep South, but the Sound’s daily heat capacity knocks a few degrees off afternoon peaks relative to inland Hattiesburg. Summer nights stay warm; winter cold fronts are brief and often moderated by returning onshore flow. It is not a dry climate — it is a maritime one. Ocean Springs sits inside subtropical live-oak maritime forest, and that biome is as much a product of the local climate as a backdrop to it. Expect summer afternoons near 32°C and winter nights near 7°C as the baseline, with about 1750 mm of precipitation across a typical year." },
  "ojai-ca": { original: "Ojai's east-west orientation gives it a last-light glow found almost nowhere else in Southern California — and a climate shaped by its amphitheater walls. Warm, dry summers and mild winters encourage citrus and olives. Afternoons can be hot inland, but the valley orientation channels cooler sea-breeze intrusions most evenings.", expanded: "Ojai's east-west orientation gives it a last-light glow found almost nowhere else in Southern California — and a climate shaped by its amphitheater walls. Warm, dry summers and mild winters encourage citrus and olives. Afternoons can be hot inland, but the valley orientation channels cooler sea-breeze intrusions most evenings. Ojai sits inside mediterranean chaparral / oak savanna, and that biome is as much a product of the local climate as a backdrop to it. Expect summer afternoons near 30°C and winter nights near 4°C as the baseline, with about 506 mm of precipitation across a typical year." },
  "orizaba-mx": { original: "Orizaba sits on the wet side of the Mexican highlands, below the country's highest peak. Gulf moisture rises into the mountains, producing frequent cloud, heavy wet-season rain, and mild temperatures that feel greener and more humid than the drier central plateau. It is a bridge between tropical Veracruz and the cool volcanic highlands.", expanded: "Orizaba sits on the wet side of the Mexican highlands, below the country's highest peak. Gulf moisture rises into the mountains, producing frequent cloud, heavy wet-season rain, and mild temperatures that feel greener and more humid than the drier central plateau. It is a bridge between tropical Veracruz and the cool volcanic highlands. The honest tradeoff is flooding, which runs elevated and worsening and is worth weighing against the mild-sounding averages. It suits cloud-forest lovers more than casual visitors chasing a postcard version of the cloud forest. Orographic lift is doing quiet work behind the numbers, and it is why Orizaba does not feel like a generic Cfb town." },
  "paducah-ky": { original: "Paducah’s climate is classically mid-South: hot, humid summers with afternoon thunderstorms; mild winters punctuated by Arctic outbreaks and freezing rain when warm Gulf air overrides cold domes at the surface. The Ohio and Tennessee rivers moderate temperatures slightly and provide moisture for fog banks in spring and fall. Convective available potential energy is high in June ahead of mesoscale convective systems that track along the river valleys.", expanded: "Paducah’s climate is classically mid-South: hot, humid summers with afternoon thunderstorms; mild winters punctuated by Arctic outbreaks and freezing rain when warm Gulf air overrides cold domes at the surface. The Ohio and Tennessee rivers moderate temperatures slightly and provide moisture for fog banks in spring and fall. Convective available potential energy is high in June ahead of mesoscale convective systems that track along the river valleys. The draw for most visitors is straightforward — quilt museum — but the climate is what keeps people coming back. Flooding and extreme summer heat are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "page-az": { original: "Page is a high-desert hub with July–August thunderstorms that paint ephemeral waterfalls on Navajo sandstone. Winters are mild and sunny; shoulder seasons are ideal for canyoneering. Lake Powell moderates immediate shoreline microclimates but does not erase the arid core.", expanded: "Page is a high-desert hub with July–August thunderstorms that paint ephemeral waterfalls on Navajo sandstone. Winters are mild and sunny; shoulder seasons are ideal for canyoneering. Lake Powell moderates immediate shoreline microclimates but does not erase the arid core. Page rewards people who plan around the high-desert escape pattern rather than treating it as scenery. Drought and extreme summer heat are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 170 mm, with summer afternoons averaging near 35°C and winter nights near -2°C — the numbers a scouting trip should actually check." },
  "palenque-mx": { original: "Palenque sits at the jungle edge: mornings can be misty; afternoons turn steamy with thunder. Rainfall is abundant year-round with a drier winter window favored by tourists. Elevation is low enough that heat never fully disappears.", expanded: "Palenque sits at the jungle edge: mornings can be misty; afternoons turn steamy with thunder. Rainfall is abundant year-round with a drier winter window favored by tourists. Elevation is low enough that heat never fully disappears. The rhythm holds most years: summer highs near 33°C, winter lows near 18°C, and about 1799 mm of precipitation overall. Tropical convective regime is the mechanism, layering a cloud forest pattern onto the Af-class averages a map alone would suggest. Palenque rewards people who plan around the cloud forest pattern rather than treating it as scenery." },
  "palm-springs-ca": { original: "Palm Springs sits in the venturi of the San Gorgonio Pass where pressure gradients translate into strong winds; winter attracts snowbirds for reliable warmth; summer pushes human activity into pools and evenings. Palm oases exploit groundwater; the surrounding desert is hyperarid.", expanded: "Palm Springs sits in the venturi of the San Gorgonio Pass where pressure gradients translate into strong winds; winter attracts snowbirds for reliable warmth; summer pushes human activity into pools and evenings. Palm oases exploit groundwater; the surrounding desert is hyperarid. The honest tradeoff is extreme summer heat, which runs very-high and worsening and is worth weighing against the mild-sounding averages. It suits retirees more than casual visitors chasing a postcard version of the high-desert escape. Gap winds is doing quiet work behind the numbers, and it is why Palm Springs does not feel like a generic BWh town." },
  "penticton-bc": { original: "Penticton sits between two lakes in one of Canada's driest valleys. Deep Pacific rain-shadow produces semi-arid summer conditions; Okanagan Lake's thermal mass moderates winter, allowing tender fruit and viable wine grapes at 49° latitude. Ponderosa pines and sagebrush fill the hillsides — a Canadian landscape with genuinely American-Southwest character. The two big lakes are the difference between living here and living in similar-latitude prairie cold.", expanded: "Penticton sits between two lakes in one of Canada's driest valleys. Deep Pacific rain-shadow produces semi-arid summer conditions; Okanagan Lake's thermal mass moderates winter, allowing tender fruit and viable wine grapes at 49° latitude. Ponderosa pines and sagebrush fill the hillsides — a Canadian landscape with genuinely American-Southwest character. The two big lakes are the difference between living here and living in similar-latitude prairie cold. The honest tradeoff is wildfire, which runs high and worsening and is worth weighing against the mild-sounding averages. It suits winemakers more than casual visitors chasing a postcard version of the rain-shadow sanctuary." },
  "pincher-creek-ab": { original: "Pincher Creek sits directly east of Crowsnest Pass, one of the strongest chinook outflow channels in North America. Winters here are wild, windy, and intermittent rather than continuous: two-day thaws to 15°C separate weeks of prairie cold. Wind gusts of 120+ km/h are recorded most winters. The landscape (fescue prairie, cottonwood riparian) reflects the chinook regime — and so do Alberta's world-leading wind-energy installations nearby.", expanded: "Pincher Creek sits directly east of Crowsnest Pass, one of the strongest chinook outflow channels in North America. Winters here are wild, windy, and intermittent rather than continuous: two-day thaws to 15°C separate weeks of prairie cold. Wind gusts of 120+ km/h are recorded most winters. The landscape (fescue prairie, cottonwood riparian) reflects the chinook regime — and so do Alberta's world-leading wind-energy installations nearby. Pincher Creek sits inside fescue prairie / foothills parkland, and that biome is as much a product of the local climate as a backdrop to it." },
  "pittsfield-ma": { original: "Pittsfield sits in a valley network that channels winter cold and summer thunderstorms along frontal boundaries. It is not as harsh as Vermont’s Northeast Kingdom, but it is dramatically different from Cape Cod on the same state license plate. Fall color and spring mud season are serious social calendars.", expanded: "Pittsfield sits in a valley network that channels winter cold and summer thunderstorms along frontal boundaries. It is not as harsh as Vermont’s Northeast Kingdom, but it is dramatically different from Cape Cod on the same state license plate. Fall color and spring mud season are serious social calendars. The draw for most visitors is straightforward — Tanglewood — but the climate is what keeps people coming back. Day-to-day life here means paying attention to seasonal extremes, not just the annual averages. Annual precipitation runs close to 1282 mm, with summer afternoons averaging near 26°C and winter nights near -8°C — the numbers a scouting trip should actually check." },
  "point-reyes-ca": { original: "Point Reyes juts 15 km into the Pacific at the Bay Area's north edge and catches the full force of California Current upwelling. The outer lighthouse recorded the highest fog frequency in the continental US. Step inland 8 km and you gain 8°C on a typical summer afternoon. The dairy ranches thriving here for 150 years are the direct consequence of the unchanging cool.", expanded: "Point Reyes juts 15 km into the Pacific at the Bay Area's north edge and catches the full force of California Current upwelling. The outer lighthouse recorded the highest fog frequency in the continental US. Step inland 8 km and you gain 8°C on a typical summer afternoon. The dairy ranches thriving here for 150 years are the direct consequence of the unchanging cool. Point Reyes Station sits inside coastal prairie / bishop pine / douglas-fir, and that biome is as much a product of the local climate as a backdrop to it." },
  "prescott-az": { original: "Prescott's 1636 m elevation earns it Ponderosa pine forest and a genuine four-season climate by Arizona standards. Summer highs hold in the 30°C range; winter brings occasional snow and freezing nights. It's one of Arizona's great summer climate refuges — heat-sensitive desert-dwellers move up for the warm months. The monsoon is reliable; sunset storms build every afternoon in July and August.", expanded: "Prescott's 1636 m elevation earns it Ponderosa pine forest and a genuine four-season climate by Arizona standards. Summer highs hold in the 30°C range; winter brings occasional snow and freezing nights. It's one of Arizona's great summer climate refuges — heat-sensitive desert-dwellers move up for the warm months. The monsoon is reliable; sunset storms build every afternoon in July and August. Elevation lapse rate is doing quiet work behind the numbers, and it is why Prescott does not feel like a generic Csa town. Expect summer afternoons near 31°C and winter nights near -2°C as the baseline, with about 459 mm of precipitation across a typical year." },
  "prince-edward-co-on": { original: "A near-island jutting into Lake Ontario, PEC enjoys measurable lake moderation and sits on a limestone plateau that drains fast and warms quickly in spring. Cool-climate wine — Pinot Noir, Chardonnay, Riesling — has flourished here since 2000.", expanded: "A near-island jutting into Lake Ontario, PEC enjoys measurable lake moderation and sits on a limestone plateau that drains fast and warms quickly in spring. Cool-climate wine — Pinot Noir, Chardonnay, Riesling — has flourished here since 2000. Lake effect is doing quiet work behind the numbers, and it is why Prince Edward County does not feel like a generic Dfb town. Expect summer afternoons near 25°C and winter nights near -8°C as the baseline, with about 965 mm of precipitation across a typical year. No single hazard dominates the risk picture here, which is itself part of the appeal." },
  "prince-rupert-bc": { original: "Prince Rupert sits at the mouth of the Skeena River, where Pacific storms slam into the Coast Mountains. Annual precipitation averages over 2600 mm; days of sunshine are few. Winter lows rarely drop below freezing; summer highs rarely exceed 18°C. Fog, drizzle, and low cloud define the sensory character. The historic cannery town of the North Coast is hyper-maritime and truly distinct within Canada.", expanded: "Prince Rupert sits at the mouth of the Skeena River, where Pacific storms slam into the Coast Mountains. Annual precipitation averages over 2600 mm; days of sunshine are few. Winter lows rarely drop below freezing; summer highs rarely exceed 18°C. Fog, drizzle, and low cloud define the sensory character. The historic cannery town of the North Coast is hyper-maritime and truly distinct within Canada. Orographic lift is the mechanism, layering a hyper-maritime pattern onto the Cfb-class averages a map alone would suggest. Expect summer afternoons near 17°C and winter nights near 1°C as the baseline, with about 2108 mm of precipitation across a typical year." },
  "puebla-mx": { original: "Puebla blends highland spring climate with serious urban pollution in winter inversions. Rain is concentrated summer–monsoon; dry season skies are cobalt. Volcanic ash soils support floriculture and maize.", expanded: "Puebla blends highland spring climate with serious urban pollution in winter inversions. Rain is concentrated summer–monsoon; dry season skies are cobalt. Volcanic ash soils support floriculture and maize. The rhythm holds most years: summer highs near 25°C, winter lows near 5°C, and about 814 mm of precipitation overall. Puebla sits inside highland oak–pine and montane agriculture, and that biome is as much a product of the local climate as a backdrop to it. It suits students more than casual visitors chasing a postcard version of the volcanic upland." },
  "puerto-escondido-mx": { original: "Puerto Escondido is the Pacific-coast capital of Mexican tropical-dry climate. The annual temperature range is narrow — highs 29–33°C, lows 18–24°C — but rainfall is highly seasonal. November through April is bone-dry, brown-landscape weather; May through October is a green explosion fed by mesoscale convective systems and occasional hurricanes. The famous surf break is partly a product of the offshore bathymetry but also of the steady trade-wind regime.", expanded: "Puerto Escondido is the Pacific-coast capital of Mexican tropical-dry climate. The annual temperature range is narrow — highs 29–33°C, lows 18–24°C — but rainfall is highly seasonal. November through April is bone-dry, brown-landscape weather; May through October is a green explosion fed by mesoscale convective systems and occasional hurricanes. The famous surf break is partly a product of the offshore bathymetry but also of the steady trade-wind regime. Diurnal sea breeze is doing quiet work behind the numbers, and it is why Puerto Escondido does not feel like a generic Aw town." },
  "puerto-vallarta-mx": { original: "Puerto Vallarta sits where bay curvature and sierra slopes focus afternoon convection. Winter is the dry, golden high season; summer brings muggy heat and Pacific storms. Sea breezes keep beaches cooler than inland Guadalajara by a wide margin.", expanded: "Puerto Vallarta sits where bay curvature and sierra slopes focus afternoon convection. Winter is the dry, golden high season; summer brings muggy heat and Pacific storms. Sea breezes keep beaches cooler than inland Guadalajara by a wide margin. It suits hospitality retirees more than casual visitors chasing a postcard version of the tropical isothermal coast. Severe-storm risk and coastal storm-surge risk are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 1072 mm, with summer afternoons averaging near 34°C and winter nights near 15°C — the numbers a scouting trip should actually check." },
  "queretaro-mx": { original: "Querétaro is a comfort-climate compromise: warmer and drier than Mexico City, less humid than lowland tropics, and increasingly urban. The dry season brings clear light and large day-night swings; the wet season arrives through afternoon storms that break heat but strain drainage in expanding districts.", expanded: "Querétaro is a comfort-climate compromise: warmer and drier than Mexico City, less humid than lowland tropics, and increasingly urban. The dry season brings clear light and large day-night swings; the wet season arrives through afternoon storms that break heat but strain drainage in expanding districts. The Köppen BSk label is the broad-stroke summary; the eternal-spring highland pattern is the fine-grained read a visit actually delivers. Expect summer afternoons near 28°C and winter nights near 7°C as the baseline, with about 484 mm of precipitation across a typical year." },
  "rapid-city-sd": { original: "Rapid City sits where Great Plains simplicity meets orographic complexity; winter can flip from arctic to spring-like in hours when downslope winds arrive.", expanded: "Rapid City sits where Great Plains simplicity meets orographic complexity; winter can flip from arctic to spring-like in hours when downslope winds arrive. At 966 m, the setting — Prairie edge at the Black Hills front — rapid weather changes when Pacific systems meet continental air — does most of the explanatory work here. Expect summer afternoons near 28°C and winter nights near -9°C as the baseline, with about 493 mm of precipitation across a typical year. The honest tradeoff is wildfire, which runs elevated and worsening and is worth weighing against the mild-sounding averages." },
  "real-catorce-mx": { original: "Real de Catorce sits at 2756 m on a mountain above a vast Chihuahuan steppe. The old silver-mining town was largely abandoned after ore played out; elevation and aridity have preserved the ruins. The climate is cool year-round (highs 20°C, lows near freezing in winter), with minimal precipitation and crystal-clear skies. Access is via a 2.3-km historic tunnel drilled through the mountain — one of Mexico's most memorable arrivals.", expanded: "Real de Catorce sits at 2756 m on a mountain above a vast Chihuahuan steppe. The old silver-mining town was largely abandoned after ore played out; elevation and aridity have preserved the ruins. The climate is cool year-round (highs 20°C, lows near freezing in winter), with minimal precipitation and crystal-clear skies. Access is via a 2.3-km historic tunnel drilled through the mountain — one of Mexico's most memorable arrivals. Elevation lapse rate is doing quiet work behind the numbers, and it is why Real de Catorce does not feel like a generic BSk town." },
  "revelstoke-bc": { original: "Revelstoke lies on the Columbia River directly between the Selkirks and Monashees. Pacific moisture that hasn't already rained out on the Coast Range is wrung out here by successive orographic barriers — producing some of the continent's heaviest snowfall zones. The town receives about 4.5 m of annual snowfall at valley level; the ski area on Mount Mackenzie averages 10 m. Summers are mild and green.", expanded: "Revelstoke lies on the Columbia River directly between the Selkirks and Monashees. Pacific moisture that hasn't already rained out on the Coast Range is wrung out here by successive orographic barriers — producing some of the continent's heaviest snowfall zones. The town receives about 4.5 m of annual snowfall at valley level; the ski area on Mount Mackenzie averages 10 m. Summers are mild and green. The Köppen Dfb label is the broad-stroke summary; the lake-effect snowbelt pattern is the fine-grained read a visit actually delivers. Expect summer afternoons near 25°C and winter nights near -6°C as the baseline, with about 865 mm of precipitation across a typical year." },
  "roswell-nm": { original: "Roswell sits in a wide valley where dryline and monsoon moisture meet; spring wind and dust are notorious. Irrigation from the Pecos supports pockets of agriculture.", expanded: "Roswell sits in a wide valley where dryline and monsoon moisture meet; spring wind and dust are notorious. Irrigation from the Pecos supports pockets of agriculture. Monsoon convective lift is doing quiet work behind the numbers, and it is why Roswell does not feel like a generic BSk town. Expect summer afternoons near 35°C and winter nights near -3°C as the baseline, with about 312 mm of precipitation across a typical year. The honest tradeoff is drought, which runs high and worsening and is worth weighing against the mild-sounding averages." },
  "salt-spring-bc": { original: "The Southern Gulf Islands receive roughly half of Vancouver's precipitation — the Olympic rain shadow extends this far north and east. Salt Spring's sheltered bays and Garry oak meadows reveal a climate more Mediterranean than most of coastal BC.", expanded: "The Southern Gulf Islands receive roughly half of Vancouver's precipitation — the Olympic rain shadow extends this far north and east. Salt Spring's sheltered bays and Garry oak meadows reveal a climate more Mediterranean than most of coastal BC. At 40 m, the setting — Southern Gulf Islands in the Olympic rain shadow — does most of the explanatory work here. Expect summer afternoons near 22°C and winter nights near 1°C as the baseline, with about 1292 mm of precipitation across a typical year. No single hazard dominates the risk picture here, which is itself part of the appeal." },
  "saltillo-mx": { original: "Saltillo sits at 1600 m in the Chihuahuan high desert, only 85 km west of Monterrey — but the elevation delivers an 8°C cooler summer afternoon on average. Winters are clear, dry, and can produce occasional frost. The altitude-tempered climate shaped the colonial founding; the city's historic position as the Camino Real's northern hub reflects the rare oasis of livable climate in a vast dry region.", expanded: "Saltillo sits at 1600 m in the Chihuahuan high desert, only 85 km west of Monterrey — but the elevation delivers an 8°C cooler summer afternoon on average. Winters are clear, dry, and can produce occasional frost. The altitude-tempered climate shaped the colonial founding; the city's historic position as the Camino Real's northern hub reflects the rare oasis of livable climate in a vast dry region. The honest tradeoff is drought, which runs elevated and worsening and is worth weighing against the mild-sounding averages. Saltillo rewards people who plan around the high-desert escape pattern rather than treating it as scenery." },
  "santa-cruz-felton-ca": { original: "The San Lorenzo Valley carves through coast-redwood forest above Santa Cruz. Summer marine layer pours up the valley each evening, feeding the tallest trees on Earth. Walk fifteen minutes from a sunny canyon bench into a fog-dripping redwood cove and the temperature drops 5°C.", expanded: "The San Lorenzo Valley carves through coast-redwood forest above Santa Cruz. Summer marine layer pours up the valley each evening, feeding the tallest trees on Earth. Walk fifteen minutes from a sunny canyon bench into a fog-dripping redwood cove and the temperature drops 5°C. Marine layer is the mechanism, layering a fog-belt coast pattern onto the Csb-class averages a map alone would suggest. Expect summer afternoons near 26°C and winter nights near 5°C as the baseline, with about 1058 mm of precipitation across a typical year. The honest tradeoff is wildfire, which runs high and worsening and is worth weighing against the mild-sounding averages." },
  "savannah-ga": { original: "Savannah’s live-oak canopy and river–ocean geometry soften peak heat compared to inland Georgia; tropical cyclones and spring severe weather still define hazard calendars.", expanded: "Savannah’s live-oak canopy and river–ocean geometry soften peak heat compared to inland Georgia; tropical cyclones and spring severe weather still define hazard calendars. The rhythm holds most years: summer highs near 33°C, winter lows near 6°C, and about 1272 mm of precipitation overall. The Köppen Cfa label is the broad-stroke summary; the hurricane-exposed coast pattern is the fine-grained read a visit actually delivers. Savannah rewards people who plan around the hurricane-exposed coast pattern rather than treating it as scenery. Coastal storm-surge risk and flooding are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "scottsbluff-ne": { original: "Scottsbluff sits where irrigation from the North Platte meets semi-arid steppe. Summer brings dryline thunderstorms; winter alternates between bitter cold and chinook relief.", expanded: "Scottsbluff sits where irrigation from the North Platte meets semi-arid steppe. Summer brings dryline thunderstorms; winter alternates between bitter cold and chinook relief. The draw for most visitors is straightforward — Scotts Bluff NM — but the climate is what keeps people coming back. Drought and extreme winter cold are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 378 mm, with summer afternoons averaging near 31°C and winter nights near -9°C — the numbers a scouting trip should actually check." },
  "spearfish-sd": { original: "Spearfish sits at a canyon mouth where stable westerly flow can descend and warm adiabatically, replacing dense cold air in the valley with dramatic speed. Such events are studied in synoptic meteorology courses because they are so readable on surface traces. Summer is warm and stormy on the Plains edge; winter is a story of wind and rapid change rather than monolithic cold.", expanded: "Spearfish sits at a canyon mouth where stable westerly flow can descend and warm adiabatically, replacing dense cold air in the valley with dramatic speed. Such events are studied in synoptic meteorology courses because they are so readable on surface traces. Summer is warm and stormy on the Plains edge; winter is a story of wind and rapid change rather than monolithic cold. The rhythm holds most years: summer highs near 29°C, winter lows near -9°C, and about 611 mm of precipitation overall. Chinook / foehn downslope is the mechanism, layering a chinook corridor pattern onto the Dwb-class averages a map alone would suggest." },
  "spokane-wa": { original: "Spokane sits where the plateau opens east of the Cascades: roughly half Seattle’s annual precipitation but real winter cold and reliable summer sun. Pacific moisture arrives in modified form; Arctic outbreaks still punch through. The river corridor organizes urban heat island and nocturnal cold drainage in the older valley neighborhoods.", expanded: "Spokane sits where the plateau opens east of the Cascades: roughly half Seattle’s annual precipitation but real winter cold and reliable summer sun. Pacific moisture arrives in modified form; Arctic outbreaks still punch through. The river corridor organizes urban heat island and nocturnal cold drainage in the older valley neighborhoods. At 562 m, the setting — Spokane River valley on the Columbia Plateau east of the Cascades — does most of the explanatory work here. Expect summer afternoons near 28°C and winter nights near -4°C as the baseline, with about 435 mm of precipitation across a typical year." },
  "squamish-bc": { original: "Squamish is where the Sea-to-Sky Highway meets the ocean: summer is warm by Vancouver standards but still maritime; winter brings heavy rain and occasional valley snow when Arctic air damps against the Strait. The eponymous wind races south when pressure gradients align — a celebrated kite- and wing-surfing engine.", expanded: "Squamish is where the Sea-to-Sky Highway meets the ocean: summer is warm by Vancouver standards but still maritime; winter brings heavy rain and occasional valley snow when Arctic air damps against the Strait. The eponymous wind races south when pressure gradients align — a celebrated kite- and wing-surfing engine. It suits climbers more than casual visitors chasing a postcard version of the fjord / inlet coast. Flooding and wildfire smoke are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 2240 mm, with summer afternoons averaging near 24°C and winter nights near 0°C — the numbers a scouting trip should actually check." },
  "st-johns-nl": { original: "St. John's holds the distinction of being North America's foggiest, cloudiest, wettest, windiest, and snowiest major city all at once — a consequence of its position on the Avalon Peninsula at the boundary of the cold Labrador Current and the North Atlantic storm track. Summers are cool (highs around 20°C); winters mild by Canadian standards but relentlessly stormy. Annual sunshine is among the lowest on the continent.", expanded: "St. John's holds the distinction of being North America's foggiest, cloudiest, wettest, windiest, and snowiest major city all at once — a consequence of its position on the Avalon Peninsula at the boundary of the cold Labrador Current and the North Atlantic storm track. Summers are cool (highs around 20°C); winters mild by Canadian standards but relentlessly stormy. Annual sunshine is among the lowest on the continent. The draw for most visitors is straightforward — iceberg watching — but the climate is what keeps people coming back. Severe-storm risk and coastal storm-surge risk are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "state-college-pa": { original: "State College sits in a valley between long parallel ridges; radiative nights run cold; spring green-up can lag neighboring ridges. Winter storms pick up moisture from the Great Lakes in northwesterly flow.", expanded: "State College sits in a valley between long parallel ridges; radiative nights run cold; spring green-up can lag neighboring ridges. Winter storms pick up moisture from the Great Lakes in northwesterly flow. It suits academics more than casual visitors chasing a postcard version of the cold-air pool. Flooding and severe-storm risk are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 1096 mm, with summer afternoons averaging near 27°C and winter nights near -6°C — the numbers a scouting trip should actually check." },
  "summerland-bc": { original: "Summerland sits mid-Okanagan on benches above the lake. Lake moderation buffers winter; rain-shadow dryness and long summer sun power one of Canada's finest orchard-vineyard climates.", expanded: "Summerland sits mid-Okanagan on benches above the lake. Lake moderation buffers winter; rain-shadow dryness and long summer sun power one of Canada's finest orchard-vineyard climates. Rain shadow is the mechanism, layering a orchard valley pattern onto the BSk-class averages a map alone would suggest. Expect summer afternoons near 27°C and winter nights near -4°C as the baseline, with about 368 mm of precipitation across a typical year. The honest tradeoff is wildfire, which runs high and worsening and is worth weighing against the mild-sounding averages. It suits viticulturalists more than casual visitors chasing a postcard version of the orchard valley." },
  "sunshine-coast-bc": { original: "The Sunshine Coast sits partially in the lee of Vancouver Island's spine, receiving noticeably more sun and less rain than the nearby mainland and the outer island coast. Mild winters, warm-ish summers by Pacific standards, and reliable shoulder seasons.", expanded: "The Sunshine Coast sits partially in the lee of Vancouver Island's spine, receiving noticeably more sun and less rain than the nearby mainland and the outer island coast. Mild winters, warm-ish summers by Pacific standards, and reliable shoulder seasons. Rain shadow is the mechanism, layering a rain-shadow sanctuary pattern onto the Csb-class averages a map alone would suggest. Expect summer afternoons near 22°C and winter nights near 3°C as the baseline, with about 1330 mm of precipitation across a typical year. No single hazard dominates the risk picture here, which is itself part of the appeal." },
  "sutton-qc": { original: "Sutton occupies the Appalachian side of southern Quebec: wetter and hillier than Montreal, less severe than the deep north, and full of small frost and slope contrasts. Valley floors cool quickly on clear nights, while south-facing slopes and village benches carry orchards, vineyards, and maple woods.", expanded: "Sutton occupies the Appalachian side of southern Quebec: wetter and hillier than Montreal, less severe than the deep north, and full of small frost and slope contrasts. Valley floors cool quickly on clear nights, while south-facing slopes and village benches carry orchards, vineyards, and maple woods. The honest tradeoff is extreme winter cold, which runs elevated and improving and is worth weighing against the mild-sounding averages. The draw for most visitors is straightforward — fall color — but the climate is what keeps people coming back. Orographic lift is the mechanism, layering a piedmont transition pattern onto the Dfb-class averages a map alone would suggest." },
  "syracuse-ny": { original: "Syracuse sits 50 km south of Lake Ontario, directly in the line of fire for the lake-effect snow machine. The city's Golden Snowball award tracks its position as America's snowiest major metropolitan area most years. Summer is humid and mild; the lake moderates extreme cold and heat compared to cities further from water.", expanded: "Syracuse sits 50 km south of Lake Ontario, directly in the line of fire for the lake-effect snow machine. The city's Golden Snowball award tracks its position as America's snowiest major metropolitan area most years. Summer is humid and mild; the lake moderates extreme cold and heat compared to cities further from water. The rhythm holds most years: summer highs near 27°C, winter lows near -7°C, and about 1086 mm of precipitation overall. Lake effect is the mechanism, layering a lake-effect snowbelt pattern onto the Dfb-class averages a map alone would suggest." },
  "taos-nm": { original: "Taos sits on a basalt plateau below the southern Sangre de Cristos. The elevation produces dramatic diurnal swings (summer highs near 27–29°C, lows in the single digits), sharp winter cold interrupted by bright sun, and a monsoon regime that reliably delivers dramatic summer thunderstorms. The light is famously extraordinary — an atmosphere-of-air quality that brought painters here for a century.", expanded: "Taos sits on a basalt plateau below the southern Sangre de Cristos. The elevation produces dramatic diurnal swings (summer highs near 27–29°C, lows in the single digits), sharp winter cold interrupted by bright sun, and a monsoon regime that reliably delivers dramatic summer thunderstorms. The light is famously extraordinary — an atmosphere-of-air quality that brought painters here for a century. The rhythm holds most years: summer highs near 29°C, winter lows near -9°C, and about 356 mm of precipitation overall. At 2124 m, the setting — Taos Plateau at the southern Sangre de Cristos — does most of the explanatory work here." },
  "tapalpa-mx": { original: "Tapalpa sits at 2020 m on a volcanic plateau in western Jalisco. Cool pine forest surrounds the town; summer afternoons rarely exceed 24°C.", expanded: "Tapalpa sits at 2020 m on a volcanic plateau in western Jalisco. Cool pine forest surrounds the town; summer afternoons rarely exceed 24°C. It suits cool-climate retreat more than casual visitors chasing a postcard version of the eternal-spring highland. Day-to-day life here means paying attention to seasonal extremes, not just the annual averages. Annual precipitation runs close to 841 mm, with summer afternoons averaging near 25°C and winter nights near 5°C — the numbers a scouting trip should actually check. The Köppen Cwb label is the broad-stroke summary; the eternal-spring highland pattern is the fine-grained read a visit actually delivers." },
  "taxco-mx": { original: "Taxco demonstrates pure lapse-rate magic: tropical latitude but high enough for cool nights and bougainvillea draped over stone streets. Afternoon thunderstorms arrive in summer with theatrical lightning over ridges.", expanded: "Taxco demonstrates pure lapse-rate magic: tropical latitude but high enough for cool nights and bougainvillea draped over stone streets. Afternoon thunderstorms arrive in summer with theatrical lightning over ridges. The draw for most visitors is straightforward — silver markets — but the climate is what keeps people coming back. Landslide and slope-stability risk and flooding are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 980 mm, with summer afternoons averaging near 28°C and winter nights near 11°C — the numbers a scouting trip should actually check." },
  "tequila-mx": { original: "The Tequila region sits at 1000–1500 m on the flanks of the Tequila Volcano, with volcanic soils rich in minerals and a climate of warm days, cool nights, and concentrated summer rains. Blue agave thrives in this specific combination — and nowhere else at meaningful scale. The 60,000-hectare agave landscape is a UNESCO World Heritage cultural site precisely because the climate-soil combination is irreplaceable.", expanded: "The Tequila region sits at 1000–1500 m on the flanks of the Tequila Volcano, with volcanic soils rich in minerals and a climate of warm days, cool nights, and concentrated summer rains. Blue agave thrives in this specific combination — and nowhere else at meaningful scale. The 60,000-hectare agave landscape is a UNESCO World Heritage cultural site precisely because the climate-soil combination is irreplaceable. It suits agrotourism more than casual visitors chasing a postcard version of the volcanic upland. Day-to-day life here means paying attention to seasonal extremes, not just the annual averages." },
  "thunder-bay-on": { original: "Thunder Bay sits on Lake Superior's north shore where Great Lakes moderation bumps into true boreal continental climate. The lake delays both winter freeze and spring warmth, keeping lakeshore milder than the Shield just inland. Summers are cool; winters long. Lake-effect snow from Superior is substantial when winds are right. The city's character — boreal forest at the back door, cold freshwater sea at the front — is distinctive.", expanded: "Thunder Bay sits on Lake Superior's north shore where Great Lakes moderation bumps into true boreal continental climate. The lake delays both winter freeze and spring warmth, keeping lakeshore milder than the Shield just inland. Summers are cool; winters long. Lake-effect snow from Superior is substantial when winds are right. The city's character — boreal forest at the back door, cold freshwater sea at the front — is distinctive. The rhythm holds most years: summer highs near 23°C, winter lows near -15°C, and about 684 mm of precipitation overall." },
  "todos-santos-mx": { original: "Todos Santos sits in a freshwater oasis on the Pacific coast of Baja Sur. The cold Pacific keeps summers several degrees cooler than the Sea of Cortez side. Winters are perfect — warm days, cool nights, sunny.", expanded: "Todos Santos sits in a freshwater oasis on the Pacific coast of Baja Sur. The cold Pacific keeps summers several degrees cooler than the Sea of Cortez side. Winters are perfect — warm days, cool nights, sunny. The Köppen BWh label is the broad-stroke summary; the desert oasis pattern is the fine-grained read a visit actually delivers. Expect summer afternoons near 34°C and winter nights near 11°C as the baseline, with about 197 mm of precipitation across a typical year. The honest tradeoff is drought, which runs high and worsening and is worth weighing against the mild-sounding averages." },
  "tofino-bc": { original: "Tofino sits on the exposed outer coast of Vancouver Island, unshielded from Pacific storms. Winter brings some of the most dramatic storm-watching on the continent — 10 m swells, 80-knot winds — and 3300 mm of annual rain. Summers are cool, damp, and fog-prone. Temperature range is tiny: January and July mean highs differ by only ~9°C.", expanded: "Tofino sits on the exposed outer coast of Vancouver Island, unshielded from Pacific storms. Winter brings some of the most dramatic storm-watching on the continent — 10 m swells, 80-knot winds — and 3300 mm of annual rain. Summers are cool, damp, and fog-prone. Temperature range is tiny: January and July mean highs differ by only ~9°C. Tofino rewards people who plan around the hyper-maritime pattern rather than treating it as scenery. Severe-storm risk and coastal storm-surge risk are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "tofino-ucluelet-corridor": { original: "Ucluelet shares its climate with Tofino — hyper-maritime, cool-summer, intensely wet. Annual precipitation exceeds 3300 mm; winter storms arrive as Pacific gales. Summer highs rarely exceed 19°C; winter lows rarely below 2°C. The temperature range over a year is only about 10°C — practically tropical in variability. Storm-watching as tourism emerged here for a reason.", expanded: "Ucluelet shares its climate with Tofino — hyper-maritime, cool-summer, intensely wet. Annual precipitation exceeds 3300 mm; winter storms arrive as Pacific gales. Summer highs rarely exceed 19°C; winter lows rarely below 2°C. The temperature range over a year is only about 10°C — practically tropical in variability. Storm-watching as tourism emerged here for a reason. Marine layer is the mechanism, layering a hyper-maritime pattern onto the Cfb-class averages a map alone would suggest. Expect summer afternoons near 18°C and winter nights near 3°C as the baseline, with about 3062 mm of precipitation across a typical year." },
  "truckee-ca": { original: "Truckee sits at 1810 m in a Sierra basin where cold air drains from surrounding peaks and pools against the Truckee River valley floor. It is among the coldest reliably-inhabited towns in California, with summer frosts in any month of the year. A 20-minute drive to Tahoe's lakeshore gains 6–10°C of moderation on a winter night — a textbook cold-pool/lake-moderation contrast inside a single watershed.", expanded: "Truckee sits at 1810 m in a Sierra basin where cold air drains from surrounding peaks and pools against the Truckee River valley floor. It is among the coldest reliably-inhabited towns in California, with summer frosts in any month of the year. A 20-minute drive to Tahoe's lakeshore gains 6–10°C of moderation on a winter night — a textbook cold-pool/lake-moderation contrast inside a single watershed. The honest tradeoff is wildfire, which runs high and worsening and is worth weighing against the mild-sounding averages. Truckee rewards people who plan around the cold-air pool pattern rather than treating it as scenery." },
  "tucson-az": { original: "Tucson’s summer rhythm is convection: moisture imported from the Gulf of California meets orographic and urban triggers. Winter brings cool days and brilliant air; hard freezes are rare in the basin floor.", expanded: "Tucson’s summer rhythm is convection: moisture imported from the Gulf of California meets orographic and urban triggers. Winter brings cool days and brilliant air; hard freezes are rare in the basin floor. Monsoon convective lift is doing quiet work behind the numbers, and it is why Tucson does not feel like a generic BWh town. Expect summer afternoons near 39°C and winter nights near 4°C as the baseline, with about 273 mm of precipitation across a typical year. The honest tradeoff is extreme summer heat, which runs very-high and worsening and is worth weighing against the mild-sounding averages." },
  "valle-guadalupe-mx": { original: "Valle de Guadalupe is a narrow granitic valley 25 km inland from Ensenada, receiving enough marine cooling most mornings to preserve Mediterranean character despite the high latitude for Mexico. Warm sunny summer afternoons give way to cool nights as marine fog creeps up the valley. Wine production — Nebbiolo, Tempranillo, Grenache, and increasingly Mediterranean whites — has made the valley one of Mexico's defining viticultural regions.", expanded: "Valle de Guadalupe is a narrow granitic valley 25 km inland from Ensenada, receiving enough marine cooling most mornings to preserve Mediterranean character despite the high latitude for Mexico. Warm sunny summer afternoons give way to cool nights as marine fog creeps up the valley. Wine production — Nebbiolo, Tempranillo, Grenache, and increasingly Mediterranean whites — has made the valley one of Mexico's defining viticultural regions. It suits winemakers more than casual visitors chasing a postcard version of the mediterranean pocket. Drought and wildfire are the two risk lines worth checking before treating the climate numbers as the whole story." },
  "viroqua-wi": { original: "The Driftless Area escaped continental glaciation; the result is a countryside with real topography, deep valleys, and ridge-valley microclimate contrasts that are rare elsewhere in the Upper Midwest. Viroqua has become the de facto center of the country's organic and cooperative farming movement — a cultural result of the climate/soil/topography permutation. Spring creeks hold water; ridgetops shed frost; south-facing slopes warm weeks ahead of north faces.", expanded: "The Driftless Area escaped continental glaciation; the result is a countryside with real topography, deep valleys, and ridge-valley microclimate contrasts that are rare elsewhere in the Upper Midwest. Viroqua has become the de facto center of the country's organic and cooperative farming movement — a cultural result of the climate/soil/topography permutation. Spring creeks hold water; ridgetops shed frost; south-facing slopes warm weeks ahead of north faces. The honest tradeoff is flooding, which runs elevated and worsening and is worth weighing against the mild-sounding averages. It suits organic farmers more than casual visitors chasing a postcard version of the driftless relief pocket." },
  "washington-dc": { original: "D.C.’s climate mixes continental and maritime air; the Potomac moderates some edges while concrete elevates nocturnal heat. Summer dew points routinely support heat indices above advisory thresholds.", expanded: "D.C.’s climate mixes continental and maritime air; the Potomac moderates some edges while concrete elevates nocturnal heat. Summer dew points routinely support heat indices above advisory thresholds. Washington sits inside humid subtropical urban forest, and that biome is as much a product of the local climate as a backdrop to it. Expect summer afternoons near 30°C and winter nights near -2°C as the baseline, with about 1191 mm of precipitation across a typical year. The honest tradeoff is flooding, which runs elevated and worsening and is worth weighing against the mild-sounding averages." },
  "wilmington-de": { original: "Wilmington sits in the transition band between maritime Mid-Atlantic and interior heat-pool air; the Brandywine gorge organizes local breezes and cold pools on clear nights.", expanded: "Wilmington sits in the transition band between maritime Mid-Atlantic and interior heat-pool air; the Brandywine gorge organizes local breezes and cold pools on clear nights. The Köppen Cfa label is the broad-stroke summary; the piedmont transition pattern is the fine-grained read a visit actually delivers. Expect summer afternoons near 29°C and winter nights near -2°C as the baseline, with about 1245 mm of precipitation across a typical year. The honest tradeoff is flooding, which runs elevated and worsening and is worth weighing against the mild-sounding averages. Wilmington rewards people who plan around the piedmont transition pattern rather than treating it as scenery." },
  "winthrop-wa": { original: "The Methow sits in one of the deepest rain shadows in the Pacific Northwest: storms unload on the Cascades to the west, leaving Winthrop with high-desert sunshine and cold, stagnant air in the valley floor during Arctic outbreaks. Cross-country skiing and dark-sky stargazing are world-class; smoke from regional fires is the summer tradeoff.", expanded: "The Methow sits in one of the deepest rain shadows in the Pacific Northwest: storms unload on the Cascades to the west, leaving Winthrop with high-desert sunshine and cold, stagnant air in the valley floor during Arctic outbreaks. Cross-country skiing and dark-sky stargazing are world-class; smoke from regional fires is the summer tradeoff. Rain shadow is the mechanism, layering a rain-shadow sanctuary pattern onto the Dsb-class averages a map alone would suggest. Expect summer afternoons near 28°C and winter nights near -6°C as the baseline, with about 478 mm of precipitation across a typical year." },
  "wolfville-ns": { original: "The Annapolis Valley lies between two parallel ridges of basalt and sandstone that shelter the valley floor from Atlantic fog and soften its maritime weather. The result is a long-settled fruit country — apple orchards since the 1600s, now with Nova Scotia's emerging cool-climate wine industry. Bay of Fundy tides and high summer sun give the valley enough heat to ripen fruit despite its northern latitude.", expanded: "The Annapolis Valley lies between two parallel ridges of basalt and sandstone that shelter the valley floor from Atlantic fog and soften its maritime weather. The result is a long-settled fruit country — apple orchards since the 1600s, now with Nova Scotia's emerging cool-climate wine industry. Bay of Fundy tides and high summer sun give the valley enough heat to ripen fruit despite its northern latitude. The honest tradeoff is severe-storm risk, which runs elevated and worsening and is worth weighing against the mild-sounding averages. The draw for most visitors is straightforward — wine trails — but the climate is what keeps people coming back." },
  "xilitla-mx": { original: "Xilitla sits on the windward Gulf slope of the Sierra Madre Oriental at 600 m. Moist Gulf air rises here and drips onto the forest almost continuously. The result is one of Mexico's lushest cloud forests, famous for the surreal sculpture garden Las Pozas.", expanded: "Xilitla sits on the windward Gulf slope of the Sierra Madre Oriental at 600 m. Moist Gulf air rises here and drips onto the forest almost continuously. The result is one of Mexico's lushest cloud forests, famous for the surreal sculpture garden Las Pozas. It suits cloud-forest dwellers more than casual visitors chasing a postcard version of the cloud forest. Flooding and landslide and slope-stability risk are the two risk lines worth checking before treating the climate numbers as the whole story. Annual precipitation runs close to 1517 mm, with summer afternoons averaging near 33°C and winter nights near 12°C — the numbers a scouting trip should actually check." },
  "yellowknife-nt": { original: "Yellowknife sits on Great Slave Lake's rocky north shore at 62.5° latitude. Winters are dark, dry, and brutal: January mean lows of −30°C, February sometimes colder. Great Slave Lake tempers the shore but freezes for half the year anyway. Summers are short, warm, and mosquito-saturated. The aurora is statistically the best in North America here.", expanded: "Yellowknife sits on Great Slave Lake's rocky north shore at 62.5° latitude. Winters are dark, dry, and brutal: January mean lows of −30°C, February sometimes colder. Great Slave Lake tempers the shore but freezes for half the year anyway. Summers are short, warm, and mosquito-saturated. The aurora is statistically the best in North America here. The honest tradeoff is extreme winter cold, which runs very-high and improving and is worth weighing against the mild-sounding averages. The draw for most visitors is straightforward — aurora — but the climate is what keeps people coming back." },
  "zacatecas-mx": { original: "Zacatecas perches at 2440 m — 500 m higher than Morelia and in a more continental interior position. The result is a colder, drier eternal-spring climate: summer highs in the low 20s, winter lows that can reach −4°C, and annual precipitation under 500 mm. It's Mexico's most genuinely cool major historic city. The rose-pink stone, silver-mining history, and cultural intensity are all at altitude.", expanded: "Zacatecas perches at 2440 m — 500 m higher than Morelia and in a more continental interior position. The result is a colder, drier eternal-spring climate: summer highs in the low 20s, winter lows that can reach −4°C, and annual precipitation under 500 mm. It's Mexico's most genuinely cool major historic city. The rose-pink stone, silver-mining history, and cultural intensity are all at altitude. The draw for most visitors is straightforward — UNESCO architecture — but the climate is what keeps people coming back. Day-to-day life here means paying attention to seasonal extremes, not just the annual averages." },
};
